PAPERS['3421-1'] = [
  Q(1, "高数", "间断点分类", "中档", 3,
    "函数 $f(x)=\\dfrac{\\ln\\left|x^2-1\\right|\\sin(x+1)}{x^2}\\cdot e^{\\frac{1}{|x|}}$ 的可去间断点个数是（　　）.",
    ["0", "1", "2", "3"], "C",
    "函数 $f(x)$ 在 $x=0,\\pm 1$ 处无定义，为间断点。计算极限：$\\lim_{x\\to -1}\\frac{\\ln|x^2-1|\\sin(x+1)}{x^2}e^{-\\frac{1}{|x|}}=0$，$\\lim_{x\\to 0}\\frac{\\ln|x^2-1|\\sin(x+1)}{x^2}e^{-\\frac{1}{|x|}}=0$，$\\lim_{x\\to 1}\\frac{\\ln|x^2-1|\\sin(x+1)}{x^2}e^{-\\frac{1}{|x|}}=\\infty$，故 $x=0,-1$ 为可去间断点，共 2 个。"),
  Q(2, "高数", "导数与函数单调性", "中档", 3,
    "已知 $f(x)$ 二阶可导，且 $f''(x)>0,\\,f(0)=-1,\\,f'(0)=1$，则函数 $f(x)$ 在 $(0,1)$ 内（　　）.",
    ["有极值点，无零点", "无极值点，无零点", "有极值点，有零点", "无极值点，有零点"], "D",
    "【法一】特殊值法：令 $f(x)=x^2+x-1$，满足条件。$f'(x)=2x+1$，在 $(0,1)$ 内单调递增，无极值点；$f(0)=-1,f(1)=1$，由零点定理知在 $(0,1)$ 内有零点。【法二】证明：$f''(x)>0$ 则 $f'(x)$ 单调递增，又 $f'(0)=1$，故 $x\\in(0,1)$ 时 $f'(x)>1$，函数在 $(0,1)$ 内无极值点。由拉格朗日中值定理，存在 $\\xi\\in(0,1)$ 使 $f(1)=f(0)+f'(\\xi)>f(0)+f'(0)=0$，再由 $f(0)=-1<0$ 及零点定理知 $f(x)$ 在 $(0,1)$ 内有零点，故选 (D)。"),
  Q(3, "高数", "反常积分敛散性", "中档", 3,
    "若对任意的正整数 $m,n$，常数 $k$ 均能满足积分 $\\int_0^{+\\infty}\\dfrac{x^k\\ln^n(x+1)}{\\sqrt{1+x^m}}\\,dx$ 收敛，则 $k$ 的取值范围为（　　）.",
    ["$\\left(-\\infty,-\\dfrac{1}{2}\\right)$", "$\\left(-2,-\\dfrac{1}{2}\\right)$", "$\\left(-2,\\dfrac{1}{2}\\right)$", "$\\left(2,+\\infty\\right)$"], "B",
    "将积分拆成 $\\int_0^1$ 与 $\\int_1^{+\\infty}$ 两部分。当 $x\\to 0$ 时，$\\frac{\\ln^n(x+1)}{x^{-k}\\sqrt{1+x^m}}\\sim\\frac{1}{x^{k-n}}$，与 $\\int_0^1\\frac{1}{x^{k-n}}dx$ 同阶同敛散，要使对任意正整数 $m,n$ 收敛，需 $-k-n<1$，即 $k>-n-1\\ge -2$，故 $k>-2$。当 $x\\to+\\infty$ 时，$\\frac{\\ln^n(x+1)}{x^{-k}\\sqrt{1+x^m}}\\sim\\frac{\\ln^n x}{x^{-k+\\frac{m}{2}}}$，要使对任意正整数 $m,n$ 收敛，需 $-k+\\frac{m}{2}>1$，即 $k<\\frac{m}{2}-1\\le -\\frac{1}{2}$，故 $k<-\\frac{1}{2}$。综上 $k\\in\\left(-2,-\\frac{1}{2}\\right)$。"),
  Q(4, "高数", "导数概念与性质", "中档", 3,
    "下列选项叙述正确的是（　　）.",
    ["若 $f(x,y)$ 在点 $(x_0,y_0)$ 处沿着任意方向的方向导数存在，则 $f(x,y)$ 在点 $(x_0,y_0)$ 处可偏导", "若 $f(x,y)$ 在点 $(x_0,y_0)$ 处沿 $(0,1)$ 与 $(0,-1)$ 的方向导数存在，则 $f(x,y)$ 在点 $(x_0,y_0)$ 处关于 $x$ 的偏导数存在", "若 $f(x,y)$ 在点 $(x_0,y_0)$ 处偏导数存在，则 $f(x,y)$ 沿着方向 $\\vec{l}=(\\cos\\alpha,\\cos\\beta)$ 的方向导数可记作 $\\left.\\dfrac{\\partial f}{\\partial \\vec{l}}\\right|_{(x_0,y_0)}=\\left.\\dfrac{\\partial f}{\\partial x}\\right|_{(x_0,y_0)}\\cos\\alpha+\\left.\\dfrac{\\partial f}{\\partial y}\\right|_{(x_0,y_0)}\\cos\\beta$", "若 $f(x,y)$ 在点 $(x_0,y_0)$ 处偏导数连续，则 $f(x,y)$ 在点 $(x_0,y_0)$ 处沿 $(0,-1)$ 方向导数为 $-\\left.\\dfrac{\\partial f}{\\partial y}\\right|_{(x_0,y_0)}$"], "D",
    "由偏导数与方向导数的关系，若 $f(x,y)$ 在 $(x_0,y_0)$ 处可微，则沿 $\\vec l=(\\cos\\alpha,\\cos\\beta)$ 的方向导数为 $\\left.\\frac{\\partial f}{\\partial\\vec l}\\right|_{(x_0,y_0)}=\\left.\\frac{\\partial f}{\\partial x}\\right|_{(x_0,y_0)}\\cos\\alpha+\\left.\\frac{\\partial f}{\\partial y}\\right|_{(x_0,y_0)}\\cos\\beta$。偏导数存在与否和方向导数存在与否无直接关系，故 (A)(B)(C) 错误。选项 (A)(B) 的反例：$f(x,y)=\\sqrt{x^2+y^2}$，在 $(0,0)$ 处任意方向的方向导数存在，但偏导数不存在。选项 (C) 的反例：$f(x,y)=\\begin{cases}1,&xy=0\\\\0,&xy\\neq0\\end{cases}$，在 $(0,0)$ 处偏导数存在但方向导数不存在。对于 (D)，偏导数连续则可微，则沿 $(0,-1)$ 方向的方向导数存在且为 $-\\left.\\frac{\\partial f}{\\partial y}\\right|_{(x_0,y_0)}$。"),
  Q(5, "线代", "二次型惯性指数", "中档", 3,
    "设二次型 $f(x_1,x_2,x_3)=(x_1+kx_2)^2+(x_1+x_3)^2-\\left[x_1-2x_2+(k+2)x_3\\right]^2$ 的负惯性指数为 $0$，则 $k=$（　　）.",
    ["$-1$", "$1$", "$-2$", "$2$"], "C",
    "原页面该题仅给出答案 (C)，解析内容在本批页面中未显示完整。"),
  Q(6, "线代", "线性方程组解的结构", "中档", 3,
    "设 $A,B$ 为 $n$ 阶矩阵，且方程组 $Ax=0$ 与方程组 $Bx=0$ 有非零公共解，则下列选项中不成立的是（　　）.",
    ["方程组 $\\begin{pmatrix}O&A^TA\\\\A^T&E\\end{pmatrix}x=0$ 与方程组 $\\begin{pmatrix}A^T&E\\\\O&A\\end{pmatrix}x=0$ 有非零公共解", "方程组 $\\begin{pmatrix}E&A\\\\O&AB\\end{pmatrix}x=0$ 与方程组 $\\begin{pmatrix}E&AB\\\\O&B\\end{pmatrix}x=0$ 有非零公共解", "方程组 $\\begin{pmatrix}A&AA^T\\\\O&A^TA\\end{pmatrix}x=0$ 与方程组 $\\begin{pmatrix}A&O\\\\A^TA&AA^T\\end{pmatrix}x=0$ 同解", "方程组 $\\begin{pmatrix}A&AB\\\\O&E\\end{pmatrix}x=0$ 与方程组 $\\begin{pmatrix}O&E\\\\A&BA\\end{pmatrix}x=0$ 同解"], "C",
    "由 $Ax=0$ 与 $Bx=0$ 有非零公共解，可得 $r\\begin{pmatrix}A\\\\B\\end{pmatrix}<n$，$r(A)<n$，$r(B)<n$。\n对于 (A)：对 $\\begin{pmatrix}O&A^TA\\\\A^T&E\\\\A^T&E\\\\O&A\\end{pmatrix}$ 作初等变换可得 $r=n+r(-AA^T)=n+r(A)<2n$，故两方程组有非零公共解，(A) 正确。\n对于 (B)：同理化为 $\\begin{pmatrix}E&O\\\\O&O\\\\O&A\\\\O&B\\end{pmatrix}$，秩为 $n+r\\begin{pmatrix}A\\\\B\\end{pmatrix}<2n$，故有非零公共解，(B) 正确。\n对于 (C)：$r\\begin{pmatrix}A&AA^T\\\\O&A^TA\\end{pmatrix}=r(A)+r(A^TA)=2r(A)$；而 $r\\begin{pmatrix}A&O\\\\A^TA&AA^T\\end{pmatrix}=r(A)+r(AA^T)=2r(A)$，但经初等变换可得 $r\\begin{pmatrix}A&AA^T\\\\O&A^TA\\\\A&O\\\\A^TA&AA^T\\end{pmatrix}=r(A)+r\\begin{pmatrix}AA^T\\\\A^TA\\end{pmatrix}$，与 $2r(A)$ 不一定相等，故 (C) 错误。\n对于 (D)：$r\\begin{pmatrix}A&AB\\\\O&E\\end{pmatrix}=r(A)+n$，$r\\begin{pmatrix}O&E\\\\A&BA\\end{pmatrix}=r(A)+n$，且 $r\\begin{pmatrix}A&AB\\\\O&E\\\\O&E\\\\A&BA\\end{pmatrix}=r(A)+n$，故两方程组同解，(D) 正确。\n综上所述，答案选 (C)。"),
  Q(7, "线代", "实对称矩阵合同相似", "难题", 4,
    "若矩阵 $A,B$ 均为三阶实对称矩阵，且矩阵 $A,B$ 可逆，则如下命题中成立的个数是（　　）．$\\newline$① 存在可逆矩阵 $P$，使得 $P^TAP=B$．$\\qquad$② 存在可逆矩阵 $P$，使得 $A^2=P^TP$．$\\newline$③ 存在可逆矩阵 $P$，使得 $P^TA^2P=B^2$．$\\qquad$④ 存在可逆矩阵 $P$，使得 $P^{-1}ABP=BA$.",
    ["1", "2", "3", "4"], "C",
    "① 条件仅有矩阵 $A,B$ 可逆，但 $A,B$ 特征值的正负性不一定相同，故 $A,B$ 不一定合同，命题①错误。\n② 矩阵 $A$ 可逆，若 $\\lambda(A)=\\lambda_1,\\lambda_2,\\lambda_3\\neq0$，则 $\\lambda(A^2)=\\lambda_1^2,\\lambda_2^2,\\lambda_3^2>0$，故 $A^2$ 与 $E$ 合同，必存在可逆矩阵 $Q$ 使 $Q^TA^2Q=E$，即 $A^2=(Q^{-1})^T(Q^{-1})$。取 $P=Q^{-1}$，则 $A^2=P^TP$，命题②正确。\n③ 由命题②可知 $A^2$ 的特征值均大于 0，同理 $B^2$ 的特征值均大于 0，故 $A^2$ 与 $B^2$ 合同，即存在可逆矩阵 $P$ 使 $P^TA^2P=B^2$，命题③正确。\n④ 若 $P=A$，则 $P^{-1}ABP=BA$，命题④正确。成立的个数为 3，答案选 (C)。"),
  Q(8, "概率", "条件概率与独立性", "中档", 3,
    "随机事件 $A,B,C$ 相互独立，满足 $P(A)=\\dfrac{1}{2},\\,P(A-B)=\\dfrac{1}{3},\\,P(C)=\\dfrac{2}{5}$，则 $P\\left\\{(C-A)\\middle|\\left(A\\cup BC\\right)\\right\\}=$（　　）.",
    ["$\\dfrac{1}{9}$", "$\\dfrac{2}{17}$", "$\\dfrac{4}{17}$", "$\\dfrac{2}{9}$"], "B",
    "事件 $A,B$ 独立，则 $P(A-B)=P(A)-P(AB)=P(A)-P(A)P(B)=\\frac{1}{3}$，由 $P(A)=\\frac{1}{2}$ 可得 $P(B)=\\frac{1}{3}$。\n$$P\\{(C-A)|(A\\cup BC)\\}=P\\{C\\bar A|(A+BC)\\}=\\frac{P(C\\bar A A+\\bar A BC)}{P(A)+P(BC)-P(ABC)}=\\frac{P(\\bar A)P(B)P(C)}{P(A)+P(B)P(C)-P(A)P(B)P(C)}$$\n$$=\\frac{\\frac{1}{2}\\times\\frac{1}{3}\\times\\frac{2}{5}}{\\frac{1}{2}+\\frac{1}{3}\\times\\frac{2}{5}-\\frac{1}{2}\\times\\frac{1}{3}\\times\\frac{2}{5}}=\\frac{2}{17}.$$\n因此答案选 (B)。"),
  Q(9, "概率", "正态分布对称性", "中档", 3,
    "设随机变量 $X$ 与 $Y$ 相互独立，且 $X\\sim N(1,2),Y\\sim N(-1,4)$，若满足等式 $P\\{X<Y\\}=P\\{X+2Y>a\\}$，则 $a=$（　　）.",
    ["$2\\sqrt{3}-1$", "$-2\\sqrt{3}+1$", "$\\sqrt{6}-1$", "$-\\sqrt{6}+1$"], "A",
    "由 $X\\sim N(1,2)$，$Y\\sim N(-1,4)$ 且独立，可得 $X-Y\\sim N(2,6)$，$\\frac{(X-Y)-2}{\\sqrt6}\\sim N(0,1)$；$X+2Y\\sim N(-1,18)$，$\\frac{(X+2Y)+1}{3\\sqrt2}\\sim N(0,1)$。\n所以 $P\\{X<Y\\}=P\\{X-Y<0\\}=P\\left\\{\\frac{(X-Y)-2}{\\sqrt6}<-\\frac{2}{\\sqrt6}\\right\\}=\\Phi\\left(-\\frac{2}{\\sqrt6}\\right)$，\n而 $P\\{X+2Y>a\\}=1-\\Phi\\left(\\frac{a+1}{3\\sqrt2}\\right)$，\n故 $\\Phi\\left(-\\frac{2}{\\sqrt6}\\right)=1-\\Phi\\left(\\frac{a+1}{3\\sqrt2}\\right)$，$\\frac{a+1}{3\\sqrt2}=\\frac{2}{\\sqrt6}$，解得 $a=2\\sqrt3-1$，答案选 (A)。"),
  Q(10, "概率", "统计量数学期望", "中档", 3,
    "设 $X_1,X_2,\\cdots X_{2n}\\,(n\\geq2)$ 为来自总体 $X$ 的简单随机样本，$X\\sim N\\left(\\mu,\\sigma^2\\right)(\\sigma>0)$，$\\overline{X}=\\dfrac{1}{2n}\\sum_{i=1}^{2n}X_i$ 为样本均值. 记统计量 $Y_1=\\sum_{i=1}^{2n}(X_i-\\overline{X})^2,\\,Y_2=\\sum_{i=1}^{n}(X_i-X_{n+i})^2,\\,Y_3=\\sum_{i=1}^{n}(X_i+X_{n+i}-2\\overline{X})^2$，则这三个统计量的数学期望 $E(Y_1),E(Y_2),E(Y_3)$ 的大小关系为（　　）.",
    ["$E(Y_1)>E(Y_2)>E(Y_3)$", "$E(Y_2)>E(Y_3)>E(Y_1)$", "$E(Y_3)>E(Y_1)>E(Y_2)$", "$E(Y_2)>E(Y_1)>E(Y_3)$"], "D",
    "对于统计量 $Y_1$：样本方差 $S^2=\\frac{1}{2n-1}\\sum_{i=1}^{2n}(X_i-\\bar X)^2$ 满足 $\\frac{(2n-1)S^2}{\\sigma^2}\\sim\\chi^2(2n-1)$，则 $E\\left[\\frac{Y_1}{\\sigma^2}\\right]=2n-1$，故 $E(Y_1)=(2n-1)\\sigma^2$。\n对于统计量 $Y_2$：$E(X_i-X_{n+i})=0$，$D(X_i-X_{n+i})=2\\sigma^2$，则 $\\frac{X_i-X_{n+i}}{\\sqrt2\\sigma}\\sim N(0,1)$ 且相互独立，因此 $\\sum_{i=1}^{n}\\left(\\frac{X_i-X_{n+i}}{\\sqrt2\\sigma}\\right)^2\\sim\\chi^2(n)$，$E(Y_2)=2n\\sigma^2$。\n比较得 $E(Y_2)>E(Y_1)>E(Y_3)$，答案选 (D)。"),
  Q(11, "高数", "隐函数求导", "常规", 2,
    "设函数 $y=y(x)$ 可由方程 $xy+\\int_0^{xy}e^{t^2}dt+1=x+e^y$ 确定，则 $\\left.\\dfrac{dy}{dx}\\right|_{x=0}=$ ________.",
    null, "-1",
    "当 $x=0$ 时，由原方程得 $y(0)=0$。在方程 $xy+\\int_0^{xy}e^{t^2}dt+1=x+e^y$ 两边对 $x$ 求导，得 $y+xy'+e^{x^2y^2}\\cdot(y+xy')=1+e^yy'$，代入 $x=0,y(0)=0$，得 $y'(0)=-1$。"),
  Q(12, "高数", "多元函数最值", "中档", 3,
    "若对于任意实数 $a,b$，不等式 $a^4+b^4-(a+b)^2\\geq A$ 恒成立，则 $A$ 的取值范围为 ________.",
    null, "(-\\infty,-2]",
    "转化为多元函数 $f(x,y)=x^4+y^4-(x+y)^2$ 在平面区域内的最小值计算。$\\frac{\\partial f}{\\partial x}=4x^3-2x-2y,\\ \\frac{\\partial f}{\\partial y}=4y^3-2x-2y$。令两式为 0，相减得 $x^3-y^3=0$，从而 $x=y$，代入得 $x^3-x=0$，解得 $x=0,\\pm1$，驻点为 $(0,0),(1,1),(-1,-1)$。二阶偏导 $\\frac{\\partial^2 f}{\\partial x^2}=12x^2-2,\\ \\frac{\\partial^2 f}{\\partial x\\partial y}=-2,\\ \\frac{\\partial^2 f}{\\partial y^2}=12y^2-2$。当 $x=y=\\pm1$ 时 $AC-B^2=96>0$ 且 $A=10>0$，为极小值点，极小值 $f(1,1)=f(-1,-1)=-2$。而 $x\\to\\infty$ 或 $y\\to\\infty$ 时 $f\\to\\infty$，故最小值为 $-2$，即 $f(x,y)\\ge-2$，$A\\le-2$。"),
  Q(13, "高数", "傅里叶级数", "中档", 3,
    "设函数 $f(x)$ 的周期为 $2\\pi$，且在 $[-\\pi,\\pi]$ 上满足 $f(x)=x^2+1$，其傅里叶级数为 $\\dfrac{a_0}{2}+\\sum_{n=1}^{\\infty}a_n\\cos nx$，则 $\\sum_{n=1}^{\\infty}(-1)^n a_n=$ ________.",
    null, "\\frac{2\\pi^2}{3}",
    "$f(x)=x^2+1$ 在 $[-\\pi,\\pi]$ 上为偶函数，故 $a_0=\\frac{2}{\\pi}\\int_0^\\pi(x^2+1)dx=2+\\frac{2\\pi^2}{3}$。周期延拓后在 $x=\\pi$ 处左右极限均为 $f(\\pi-0)=f(\\pi+0)=\\pi^2+1$。由收敛定理，在 $x=\\pi$ 处 $\\frac{a_0}{2}+\\sum_{n=1}^{\\infty}a_n\\cos n\\pi=\\pi^2+1$。因为 $\\cos n\\pi=(-1)^n$，所以 $\\sum_{n=1}^{\\infty}(-1)^na_n=\\pi^2+1-\\frac{a_0}{2}=\\pi^2+1-\\left(1+\\frac{\\pi^2}{3}\\right)=\\frac{2\\pi^2}{3}$。"),
  Q(14, "高数", "曲线积分与路径无关", "中档", 3,
    "若函数 $f(x)$ 可导，且 $f(1)=1$，曲线 $L$ 为右半平面 $(x>0)$ 内的光滑曲线，积分 $\\int_L xyf(x)dx+\\left[x^2-xf'(x)\\right]dy$ 与路径无关，则 $f(x)=$ ________.",
    null, "\\frac{2(x-1)}{x}+\\frac{e^{1-x}}{x}",
    "令 $P(x,y)=xyf(x),\\ Q(x,y)=x^2-xf(x)$，因积分与路径无关，$\\frac{\\partial P}{\\partial y}=\\frac{\\partial Q}{\\partial x}$，即 $xf(x)=2x-f(x)-xf'(x)$，整理得 $f'(x)+\\left(1+\\frac{1}{x}\\right)f(x)=2$。解此一阶线性微分方程得 $f(x)=\\frac{2(x-1)}{x}+\\frac{C}{x}e^{-x}$。代入 $f(1)=1$ 得 $C=e$，故 $f(x)=\\frac{2(x-1)}{x}+\\frac{e^{1-x}}{x}$。"),
  Q(15, "线代", "特征值与行列式", "中档", 3,
    "矩阵 $A,B$ 均为三阶矩阵，其中矩阵 $A$ 不可逆，矩阵 $B$ 满足 $(A+E)B=O$，$r(B)=2$，则 $|A+2E|=$ ______.",
    null, "2",
    "矩阵 $A$ 不可逆，故必有特征值 0。由 $(A+E)B=O$ 得 $AB=-B$，记 $B=(\\alpha_1,\\alpha_2,\\alpha_3)$，则 $A(\\alpha_1,\\alpha_2,\\alpha_3)=-(\\alpha_1,\\alpha_2,\\alpha_3)$，即 $B$ 的每一非零列均为 $A$ 对应特征值 $-1$ 的特征向量。又 $r(B)=2$，故特征值 $-1$ 对应两个线性无关的特征向量，$-1$ 至少是 $A$ 的二重特征值。故 $\\lambda(A)=0,-1,-1$，从而 $\\lambda(A+2E)=2,1,1$，$|A+2E|=2$。"),
  Q(16, "概率", "条件概率与分布", "中档", 3,
    "已知二维随机变量 $(X,Y)$ 的联合概率密度为 $f(x,y)=\\begin{cases}\\dfrac{1}{x},&0<y<x<1,\\\\0,&\\text{其他},\\end{cases}$ 则当 $0<x<1$ 时，条件概率 $P\\{X+Y\\leq1\\big|X=x\\}=$ ________.",
    null, "\\begin{cases}1, & 0<x\\le\\frac{1}{2},\\\\ \\frac{1-x}{x}, & \\frac{1}{2}<x<1\\end{cases}",
    "边缘概率密度 $f_X(x)=\\int_{-\\infty}^{+\\infty}f(x,y)dy=\\int_0^x\\frac{1}{x}dy\\ (0<x<1)$，其他为 0。故条件概率密度 $f_{Y|X}(y|x)=\\frac{f(x,y)}{f_X(x)}=\\begin{cases}\\frac{1}{x},&0<y<x<1,\\\\0,&\\text{其他}\\end{cases}$。条件概率 $P\\{X+Y\\le1|X=x\\}=P\\{Y\\le1-x|X=x\\}=\\int_{-\\infty}^{1-x}f_{Y|X}(y|x)dy$。当 $x\\le1-x$ 即 $x\\le\\frac{1}{2}$ 时，$P\\{Y\\le1-x|X=x\\}=\\int_0^x\\frac{1}{x}dy=1$；当 $x>1-x$ 即 $\\frac{1}{2}<x$ 时，$P\\{Y\\le1-x|X=x\\}=\\int_0^{1-x}\\frac{1}{x}dy=\\frac{1-x}{x}$。综上所述 $P\\{X+Y\\le1|X=x\\}=\\begin{cases}1,&0<x\\le\\frac{1}{2}\\\\ \\frac{1-x}{x},&\\frac{1}{2}<x<1\\end{cases}$。（注：写成 $x\\le\\frac{1}{2}$ 与 $\\frac{1}{2}<x$ 不扣分）"),
  Q(17, "高数", "导数定义与切线方程", "难题", 4,
    "设连续的奇函数 $y=f(x)$ 在 $x=1$ 处可导，且在 $x=0$ 的去心邻域内满足等式$$2f(x)+f(-x)=\\dfrac{\\sqrt{1+2f\\left(e^x\\right)}-\\sqrt{1-f\\left(1-\\tan x\\right)}}{x}-1\\cdot$$试求 $y=f(x)$ 在 $x=-1$ 处的切线方程.",
    null, "y=2x+2",
    "由条件可得 $\\lim_{x\\to0}[2f(x)+f(-x)]=\\lim_{x\\to0}\\left[\\frac{\\sqrt{1+2f(e^x)}-\\sqrt{1-f(1-\\tan x)}}{x}\\right]-1$。因 $f$ 连续，左边 $=3f(0)=0$，则 $\\lim_{x\\to0}\\frac{\\sqrt{1+2f(e^x)}-\\sqrt{1-f(1-\\tan x)}}{x}=1$。又 $\\lim_{x\\to0}\\left[\\sqrt{1+2f(e^x)}-\\sqrt{1-f(1-\\tan x)}\\right]=\\sqrt{1+2f(1)}-\\sqrt{1-f(1)}=0$，可得 $f(1)=0$。由分子有理化：$$\\lim_{x\\to0}\\frac{\\sqrt{1+2f(e^x)}-\\sqrt{1-f(1-\\tan x)}}{x}=\\lim_{x\\to0}\\frac{2f(e^x)+f(1-\\tan x)}{x\\left[\\sqrt{1+2f(e^x)}+\\sqrt{1-f(1-\\tan x)}\\right]}=\\lim_{x\\to0}\\frac{2f(e^x)-2f(1)+f(1-\\tan x)-f(1)}{2x}$$ $$=\\lim_{x\\to0}\\left[\\frac{f(e^x)-f(1)}{e^x-1}\\cdot\\frac{e^x-1}{x}+\\frac{f(1-\\tan x)-f(1)}{-\\tan x}\\cdot\\frac{-\\tan x}{2x}\\right]=f'(1)-\\frac{1}{2}f'(1)=\\frac{1}{2}f'(1)=1$$ 所以 $f'(1)=2$。由 $y=f(x)$ 为奇函数，$f(-1)=-f(1)=0$，$f'(-1)=f'(1)=2$，故在 $x=-1$ 处的切线方程为 $y=2x+2$。（本题不能使用洛必达，使用洛必达直接扣 5 分）"),
  Q(18, "高数", "偏导数变量代换", "中档", 3,
    "设二元函数 $z=z(x,y)$ 具有二阶连续偏导数，且满足 $2\\dfrac{\\partial^2z}{\\partial x^2}-3\\dfrac{\\partial^2z}{\\partial x\\partial y}-2\\dfrac{\\partial^2z}{\\partial y^2}=25e^{3x-y}$. 作变量代换 $u=2x+y$，$v=x-2y$，记 $z(x,y)=f(u,v)$.（1）求 $\\dfrac{\\partial^2 f}{\\partial u\\partial v}$；（2）若 $\\dfrac{\\partial f(u,0)}{\\partial u}=e^u+2u$，$f(0,v)=e^v+v^2+1$，求 $z(x,y)$ 的表达式.",
    null, "(1) \\frac{\\partial^2 f}{\\partial u\\partial v}=e^{u+v}；(2) z(x,y)=e^{3x-y}+5x^2+5y^2+1",
    "(1) 由复合函数求导法则，得 $\\frac{\\partial z}{\\partial x}=2f_u+f_v$，$\\frac{\\partial z}{\\partial y}=f_u-2f_v$，则 $\\frac{\\partial^2 z}{\\partial x^2}=4f_{uu}+4f_{uv}+f_{vv}$，$\\frac{\\partial^2 z}{\\partial x\\partial y}=2f_{uu}-3f_{uv}-2f_{vv}$，$\\frac{\\partial^2 z}{\\partial y^2}=f_{uu}-4f_{uv}+4f_{vv}$。代入原方程，得 $25f_{uv}=25e^{u+v}$，故 $\\frac{\\partial^2 f}{\\partial u\\partial v}=e^{u+v}$。(2) 对 $v$ 积分得 $f_u=e^{u+v}+C(u)$；令 $v=0$，由 $f_u(u,0)=e^u+2u$ 得 $C(u)=2u$，所以 $f_u=e^{u+v}+2u$。对 $u$ 积分得 $f(u,v)=e^{u+v}+u^2+C(v)$；令 $u=0$，由 $f(0,v)=e^v+v^2+1$ 得 $C(v)=v^2+1$，所以 $f(u,v)=e^{u+v}+u^2+v^2+1$。将 $u=2x+y$，$v=x-2y$ 代入，化简得 $z(x,y)=e^{3x-y}+5x^2+5y^2+1$。"),
  Q(19, "高数", "第二型曲面积分", "难题", 4,
    "设连续函数 $f(x,y)$ 满足$$f(x,y)=2(x-y)^2+\\iint_{\\Sigma}x(e^z-2z^2)\\,dydz+y(e^z-2z^2)\\,dzdx+\\left[zf(x,y)-2(e^z-1)\\right]dxdy,$$其中 $\\Sigma$ 为球面 $x^2+y^2+z^2=1$（$z\\geq0$）的上半部分，取上侧，求 $\\iint_{\\Sigma}f(x,y)\\,dS$.",
    null, "\\frac{8\\pi}{3}",
    "设 $A=\\iint_{\\Sigma} x(e^z-2z^2)dydz+y(e^z-2z^2)dzdx+[zf(x,y)-2(e^z-1)]dxdy$，则 $f(x,y)=2(x-y)^2+A$。补面 $\\Sigma_1=\\{(x,y,z)\\mid x^2+y^2\\le 1,z=0\\}$ 取下侧，由高斯公式得 $\\iiint_{\\Omega}[f(x,y)-4z^2]dV=\\iiint_{\\Omega}[2x^2+2y^2-4z^2-4xy+A]dV=A\\iiint_{\\Omega}dV=\\frac{2\\pi}{3}A$（由对称性 $\\iiint_\\Omega x^2dV=\\iiint_\\Omega y^2dV=\\iiint_\\Omega z^2dV$，$\\iiint_\\Omega xydV=0$）。又 $\\Sigma_1$ 上 $z=0$，$\\iint_{\\Sigma_1}-2(e^0-1)dxdy=0$，故 $A=\\frac{2\\pi}{3}A$，解得 $A=0$，所以 $f(x,y)=2(x-y)^2$。曲面 $\\Sigma$ 关于 $yOz$ 平面对称，$\\iint_\\Sigma xydS=0$，$\\iint_\\Sigma f\\,dS=2\\iint_\\Sigma(x^2+y^2)dS=8\\iint_{\\Sigma_2}(x^2+y^2)dS$（$\\Sigma_2$ 为第一卦限部分）。由轮换对称性 $\\iint_{\\Sigma_2}x^2dS=\\iint_{\\Sigma_2}y^2dS=\\iint_{\\Sigma_2}z^2dS=\\frac{1}3\\iint_{\\Sigma_2}(x^2+y^2+z^2)dS=\\frac{\\pi}{6}$，故 $\\iint_\\Sigma f(x,y)dS=8\\left(\\frac{\\pi}{6}+\\frac{\\pi}{6}\\right)=\\frac{8\\pi}{3}$。"),
  Q(20, "高数", "数列极限与单调有界", "难题", 4,
    "若数列 $\\{x_n\\}$ 满足 $x_{n+1}=1+\\ln\\left(\\dfrac{x_n^2}{1+\\ln x_n}\\right)$，其中 $n=1,2,...$，且 $x_1=a>1$.（1）证明：对于任意的正整数 $n$，都有 $x_n>1$.（2）证明数列 $\\{x_n\\}$ 收敛，并计算 $\\lim_{n\\to\\infty}x_n$.",
    null, "\\lim_{n\\to\\infty}x_n=1",
    "(1) 记 $f(x)=x^2-1-\\ln x\\ (x\\ge1)$，$f'(x)=2x-\\frac1x>0$，$f$ 在 $[1,+\\infty)$ 单调递增，故 $x\\ge1$ 时 $f(x)>f(1)=0$，即 $x>1$ 时 $x^2>1+\\ln x$。因此 $x_1=a>1$ 时 $\\frac{x_1^2}{1+\\ln x_1}>1$，$x_2>1$；由数学归纳法，若 $x_k>1$，则 $\\frac{x_k^2}{1+\\ln x_k}>1$，得 $x_{k+1}>1$。综上 $x_n>1$，数列有下界。(2) 记 $g(x)=1+2\\ln x-\\ln(1+\\ln x)-x\\ (x>1)$，$g'(x)=\\frac{1+2\\ln x-x-x\\ln x}{x(1+\\ln x)}$。再令 $\\varphi(x)=1+2\\ln x-x-x\\ln x$，$\\varphi'(x)=\\frac2x-2-\\ln x<0$（$x>1$），$\\varphi(x)<\\varphi(1)=0$；又 $g'(x)=\\frac{\\varphi(x)}{x(1+\\ln x)}<0$，$g(x)<g(1)=0$。故 $x_n>1$ 时 $x_{n+1}-x_n=g(x_n)<0$，数列单调递减。由单调有界原理，$\\{x_n\\}$ 收敛。记 $A=\\lim_{n\\to\\infty}x_n$，对 $x_{n+1}=1+\\ln\\frac{x_n^2}{1+\\ln x_n}$ 两侧取极限得 $A=1+\\ln\\frac{A^2}{1+\\ln A}$，解得 $A=1$，即 $\\lim_{n\\to\\infty}x_n=1$。"),
  Q(21, "线代", "矩阵相似对角化", "难题", 4,
    "若矩阵 $A=\\begin{pmatrix}5&-a&0\\\\1&a+2&0\\\\0&0&2\\end{pmatrix}$ 不可相似对角化，其中 $a$ 为参数.（1）计算 $a$ 的取值；（2）判断是否存在可逆矩阵 $P$，使得 $P^{-1}AP=B$，其中 $B=\\begin{pmatrix}2a+2&2&0\\\\0&2a+2&0\\\\0&0&2\\end{pmatrix}$. 若不存在，说明理由；若存在，试找出一个满足的可逆矩阵 $P$.",
    null, "(1) a=1 或 a=9；(2) a=9 时不存在；a=1 时存在可逆矩阵 P 使 P^{-1}AP=B",
    "(1) $|A-\\lambda E|=(2-\\lambda)[\\lambda^2-(a+7)\\lambda+6a+10]$。① 若 $\\lambda=2$ 为三重特征值，则 $a+7=4,6a+10=4$，无解。② 若 $\\lambda=2$ 为二重特征值，代入得 $a=0$，此时 $r(A-2E)=1$，$\\lambda=2$ 对应两个线性无关的特征向量，$A$ 能相似对角化，不满足。③ 若 $\\lambda^2-(a+7)\\lambda+6a+10=0$ 出现二重根，$\\Delta=(a-1)(a-9)=0$。当 $a=1$ 时 $\\lambda=4$ 为二重，$r(A-4E)=2$，只有一个线性无关特征向量，$A$ 不能相似对角化；当 $a=9$ 时 $\\lambda=8$ 为二重，$r(A-8E)=2$，$A$ 不能相似对角化。综上 $a=1$ 或 $a=9$。(2) 当 $a=9$ 时，$B$ 特征值为 $20,20,2$，与 $A$ 的特征值不同，故不可能相似于 $B$。当 $a=1$ 时，$B=\\begin{pmatrix}4&2&0\\\\0&4&0\\\\0&0&2\\end{pmatrix}$，设 $P=(\\alpha_1,\\alpha_2,\\alpha_3)$ 满足 $P^{-1}AP=B$，则 $(A\\alpha_1,A\\alpha_2,A\\alpha_3)=(4\\alpha_1,\\,2\\alpha_1+4\\alpha_2,\\,2\\alpha_3)$，即 $A\\alpha_1=4\\alpha_1$，$A\\alpha_2=2\\alpha_1+4\\alpha_2$，$A\\alpha_3=2\\alpha_3$。由 $(A-4E)\\alpha_1=0$ 解得 $\\alpha_1=(k_1,0,0)^T$（页面至此，后续求解过程见下页）。"),
  Q(22, "概率", "参数估计", "中档", 3,
    "设随机变量 $X$ 与 $Y$ 相互独立，且 $X$ 在区间 $[-2,2]$ 上服从均匀分布，$Y$ 的概率密度为 $f(y)=\\dfrac{\\lambda}{2}e^{-\\lambda|y|}$，$-\\infty<y<+\\infty$，其中参数 $\\lambda(\\lambda>0)$ 未知. 令 $Z=\\begin{cases}2Y,&X\\geq1,\\\\-2Y,&X<1.\\end{cases}$（1）求随机变量 $Z$ 的概率密度；（2）若 $Z_1,Z_2,\\cdots,Z_n$ 为来自总体 $Z$ 的简单随机样本，求参数 $\\lambda$ 的矩估计量和最大似然估计量.",
    null, "$\\hat\\lambda_1=\\sqrt{8n\\Big/\\sum\\limits_{i=1}^{n}Z_i^2}$，$\\hat\\lambda_2=2n\\Big/\\sum\\limits_{i=1}^{n}|Z_i|$",
    "（1）随机变量 $Z$ 的分布函数为：$F_Z(z)=P\\{Z\\le z\\}=P\\{2Y\\le z,X\\ge1\\}+P\\{-2Y\\le z,X<1\\}=P\\{Y\\le\\frac z2\\}P\\{X\\ge1\\}+P\\{Y\\ge-\\frac z2\\}P\\{X<1\\}=\\frac{1}4P\\{Y\\le\\frac z2\\}+\\frac{3}4P\\{Y\\ge-\\frac z2\\}=\\frac{1}4F_Y(\\frac z2)+\\frac{3}4[1-F_Y(-\\frac z2)],\\ z\\in(-\\infty,+\\infty)$。故 $f_Z(z)=F_Z'(z)=\\frac{1}8f_Y(\\frac z2)+\\frac{3}8f_Y(-\\frac z2)=\\frac{\\lambda}{16}e^{\\frac{-\\lambda|z|}{2}}+\\frac{3\\lambda}{16}e^{\\frac{-\\lambda|z|}{2}}=\\frac{\\lambda}{4}e^{\\frac{-\\lambda|z|}{2}},\\ z\\in(-\\infty,+\\infty)$，即 $f_Z(z)=\\frac{\\lambda}{4}e^{\\frac{-\\lambda|z|}{2}},\\ z\\in(-\\infty,+\\infty)$。（2）①矩估计：易知 $EZ=0$，故选用二阶原点矩进行矩估计，$EZ^2=\\int_{-\\infty}^{+\\infty}z^2\\cdot\\frac{\\lambda}{4}e^{\\frac{-\\lambda|z|}{2}}dz=\\frac{\\lambda}{2}\\int_0^{+\\infty}z^2e^{-\\frac{\\lambda}{2}z}dz\\xrightarrow{t=\\frac{\\lambda}{2}z}\\frac{\\lambda}{2}\\cdot\\frac{8}{\\lambda^3}\\int_0^{+\\infty}t^2e^{-t}dt=\\frac{8}{\\lambda^2}$。令 $EZ^2=\\frac1n\\sum_{i=1}^nZ_i^2$，即 $\\frac{8}{\\lambda^2}=\\frac1n\\sum_{i=1}^nZ_i^2$，得矩估计量 $\\hat\\lambda_1=\\sqrt{8n\\big/\\sum_{i=1}^nZ_i^2}$。②最大似然估计：似然函数 $L(\\lambda)=(\\frac{\\lambda}{4})^ne^{-\\frac{\\lambda}{2}\\sum_{i=1}^n|Z_i|}$，从而 $\\ln L(\\lambda)=n\\ln(\\lambda)-n\\ln4-\\frac{\\lambda}{2}\\sum_{i=1}^n|Z_i|$。令 $\\frac{d\\ln L(\\lambda)}{d\\lambda}=\\frac n\\lambda-\\frac{1}2\\sum_{i=1}^n|Z_i|=0$，解得最大似然估计值 $\\hat\\lambda_2=2n\\big/\\sum_{i=1}^n|Z_i|$。"),
];

/* 崔命六套卷（数二）· 卷二 · 伪年份 3422-2 · 22 题 */
PAPERS['3422-2'] = [
  Q(1, "高数", "函数间断点分类", "中档", 3,
    "函数 $f(x)=\\dfrac{\\ln\\left|x^2-1\\right|\\sin(x+1)}{x^2}\\cdot e^{\\frac{1}{|x|}}$ 的可去间断点个数是（　　）.",
    ["0", "1", "2", "3"], "C",
    "函数 $f(x)$ 在 $x=0,\\pm1$ 处无定义，$x=0,\\pm1$ 为间断点.\n$$\\lim_{x\\to-1}\\frac{\\ln|x^2-1|\\sin(x+1)}{x^2}\\cdot e^{\\frac{1}{|x|}}=0,\\quad \\lim_{x\\to0}\\frac{\\ln|x^2-1|\\sin(x+1)}{x^2}\\cdot e^{\\frac{1}{|x|}}=0,\\quad \\lim_{x\\to1}\\frac{\\ln|x^2-1|\\sin(x+1)}{x^2}\\cdot e^{\\frac{1}{|x|}}=\\infty,$$\n故 $x=0,-1$ 为 $f(x)$ 的可去间断点. 答案选（C）."),
  Q(2, "高数", "分段函数可导性", "中档", 3,
    "若函数 $f(x)=\\begin{cases}ax^2+b\\sin x+c, & x\\le 0,\\\\ \\ln(1+x), & x>0\\end{cases}$ 在 $x=0$ 处一阶导函数连续但二阶导数不存在，则 $a,b,c$ 满足（　　）.",
    ["$a\\neq-\\dfrac{1}{2},b=1,c=0$", "$a\\neq\\dfrac{1}{2},b=0,c=0$", "$a=-\\dfrac{1}{2},b=1,c=0$", "$a=-\\dfrac{1}{2},b=0,c=1$"], "A",
    "因 $f(0^-)=c, f(0^+)=0, f(0)=c$，又 $f(x)$ 在 $x=0$ 连续，所以 $c=0$.\n由 $f_-‘(0)=\\lim_{x\\to0^-}\\frac{f(x)-f(0)}{x}=\\lim_{x\\to0^-}\\frac{ax^2+b\\sin x-0}{x}=b$，\n$$f_+’(0)=\\lim_{x\\to0^+}\\frac{f(x)-f(0)}{x}=\\lim_{x\\to0^+}\\frac{\\ln(1+x)-0}{x}=1,$$\n所以 $b=1$ 时，$f'(0^-)=1, f'(0^+)=1, f'(0)=1$，$f'(x)$ 在 $x=0$ 处连续且\n$$f'(x)=\\begin{cases}2ax+\\cos x, & x<0,\\\\ 1, & x=0,\\\\ \\frac{1}{1+x}, & x>0.\\end{cases}$$\n$$f''(0)=\\lim_{x\\to0}\\frac{f'(x)-f'(0)}{x}=\\begin{cases}\\lim_{x\\to0^-}\\frac{2ax+\\cos x-1}{x}=2a,\\\\ \\lim_{x\\to0^+}\\frac{\\frac{1}{1+x}-1}{x}=\\lim_{x\\to0^+}\\frac{-x}{x(1+x)}=-1,\\end{cases}$$\n当 $2a\\ne-1$，即 $a\\ne-\\frac{1}{2}$ 时，$f(x)$ 在 $x=0$ 处二阶不可导. 综上，$a\\ne-\\frac{1}{2}, b=1, c=0$，答案选（A）."),
  Q(3, "高数", "导数不等式与函数单调性", "中档", 3,
    "已知 $f(x)$ 二阶可导，且 $f''(x)>0, f(0)=-1, f'(0)=1$，则函数 $f(x)$ 在 $(0,1)$ 内（　　）.",
    ["有极值点，无零点", "无极值点，无零点", "有极值点，有零点", "无极值点，有零点"], "D",
    "【法一】特殊值法\n令 $f(x)=x^2+x-1$，满足 $f''(x)>0, f(0)=-1, f'(0)=1$，\n$f'(x)=2x+1$，函数 $f(x)$ 在 $(0,1)$ 内单调递增，无极值点.\n对于 $f(x)=x^2+x-1$，$f(0)=-1, f(1)=1$，由零点定理，函数 $f(x)$ 在 $(0,1)$ 内有零点.\n【法二】证明\n由于 $f''(x)>0$，则 $f'(x)$ 单调递增，又 $f'(0)=1$，所以当 $x\\in(0,1)$ 时，$f'(x)>1$，\n故函数 $f(x)$ 在 $(0,1)$ 内无极值点.\n对 $f(x)$ 在 $[0,1]$ 上用拉格朗日中值定理，存在 $\\xi\\in(0,1)$，使得 $f(1)-f(0)=f'(\\xi)(1-0)$，即 $f(1)=f(0)+f'(\\xi)$.\n于是，$f(1)=f(0)+f'(\\xi)>f(0)+f'(0)=0$，再由 $f(0)=-1<0$ 及零点定理，可知函数 $f(x)$ 在 $(0,1)$ 内有零点，故选（D）."),
  Q(4, "高数", "反常积分敛散性", "中档", 3,
    "若对任意的正整数 $m,n$，常数 $k$ 均能满足积分 $\\displaystyle\\int_0^{+\\infty}\\frac{x^k\\ln^n(x+1)}{\\sqrt{1+x^m}}dx$ 收敛，则 $k$ 的取值范围为（　　）.",
    ["$\\left(-\\infty,-\\dfrac{1}{2}\\right)$", "$\\left(-2,-\\dfrac{1}{2}\\right)$", "$\\left(-2,\\dfrac{1}{2}\\right)$", "$(2,+\\infty)$"], "B",
    "被积函数 $\\int_0^{+\\infty}\\frac{x^k\\ln^n(x+1)}{\\sqrt{1+x^m}}dx$ 在 $x=0$ 处可能会出现瑕点，因此将反常积分分成两个部分，\n$$\\text{即}\\int_0^{+\\infty}\\frac{x^k\\ln^n(x+1)}{\\sqrt{1+x^m}}dx=\\int_0^1\\frac{x^k\\ln^n(x+1)}{\\sqrt{1+x^m}}dx+\\int_1^{+\\infty}\\frac{x^k\\ln^n(x+1)}{\\sqrt{1+x^m}}dx.$$\n积分 $\\int_0^{+\\infty}\\frac{x^k\\ln^n(x+1)}{\\sqrt{1+x^m}}dx$ 收敛，当且仅当 $\\int_0^1\\frac{x^k\\ln^n(x+1)}{\\sqrt{1+x^m}}dx$ 与 $\\int_1^{+\\infty}\\frac{x^k\\ln^n(x+1)}{\\sqrt{1+x^m}}dx$ 均收敛才满足.\n$$\\int_0^1\\frac{x^k\\ln^n(x+1)}{\\sqrt{1+x^m}}dx=\\int_0^1\\frac{\\ln^n(x+1)}{x^{-k}\\sqrt{1+x^m}}dx,$$ 根据极限审敛法，当 $x\\to0$ 时，$\\frac{\\ln^n(x+1)}{x^{-k}\\sqrt{1+x^m}}\\sim\\frac{x^n}{x^{-k}}=\\frac{1}{x^{k-n}}$，因此 $\\int_0^1\\frac{x^k\\ln^n(x+1)}{\\sqrt{1+x^m}}dx$ 与 $\\int_0^1\\frac{1}{x^{k-n}}dx$ 同阶同敛散.\n要使得对任意正整数 $m,n$ 均满足 $\\int_0^1\\frac{1}{x^{k-n}}dx$ 收敛，则满足 $-k-n<1$，$k>-n-1\\ge-2$，所以 $k>-2$，任意的正整数 $m,n$，均有 $\\int_0^1\\frac{x^k\\ln^n(x+1)}{\\sqrt{1+x^m}}dx$ 收敛.\n$$\\int_1^{+\\infty}\\frac{x^k\\ln^n(x+1)}{\\sqrt{1+x^m}}dx=\\int_1^{+\\infty}\\frac{\\ln^n(x+1)}{x^{-k}\\sqrt{1+x^m}}dx,$$ 根据极限审敛法，当 $x\\to+\\infty$ 时，$\\frac{\\ln^n(x+1)}{x^{-k}\\sqrt{1+x^m}}\\sim\\frac{\\ln^n x}{x^{-k+\\frac{m}{2}}}$，因此\n$$\\int_1^{+\\infty}\\frac{x^k\\ln^n(x+1)}{\\sqrt{1+x^m}}dx=\\int_1^{+\\infty}\\frac{\\ln^n x}{x^{-k+\\frac{m}{2}}}dx\\ \\text{同阶同敛散}.$$\n要使得对任意正整数 $m,n$ 均满足 $\\int_1^{+\\infty}\\frac{\\ln^n x}{x^{-k+\\frac{m}{2}}}dx$ 收敛，则满足 $-k+\\frac{m}{2}>1$，$k<\\frac{m}{2}-1\\le-\\frac{1}{2}$，所以 $k<-\\frac{1}{2}$，任意的正整数 $m,n$，均有 $\\int_1^{+\\infty}\\frac{x^k\\ln^n(x+1)}{\\sqrt{1+x^m}}dx$ 收敛.\n综上所述，常数 $k$ 的取值范围为 $\\left(-2,-\\frac{1}{2}\\right)$，答案选（B）."),
  Q(5, "高数", "一阶齐次微分方程", "难题", 4,
    "若微分方程 $y'=ax^{\\alpha}+by^{\\beta}\\ (\\alpha\\beta\\neq0,ab\\neq0)$ 经变换 $y=z^m$ 可化为一阶齐次方程 $\\dfrac{dz}{dx}=f\\left(\\dfrac{z}{x}\\right)$，则常数 $\\alpha,\\beta$ 满足（　　）.",
    ["$\\dfrac{1}{\\beta}-\\dfrac{1}{\\alpha}=1$", "$\\dfrac{1}{\\alpha}-\\dfrac{1}{\\beta}=1$", "$\\dfrac{1}{\\beta}+\\dfrac{1}{\\alpha}=1$", "$\\dfrac{1}{\\beta}-\\dfrac{1}{\\alpha}=0$"], "当 $a=1$ 时，存在可逆矩阵 $P=\\begin{pmatrix}k_1&2k_1+k_2&0\\\\k_1&k_2&0\\\\0&0&k_3\\end{pmatrix}$（其中 $k_1\\neq0,k_3\\neq0$），使得 $P^{-1}AP=B$。",
    "$A\\alpha_1=4\\alpha_1\\rightarrow(A-4E)\\alpha_1=0$，$A-4E=\\begin{pmatrix}1&-1&0\\\\1&-1&0\\\\0&0&-2\\end{pmatrix}$，解得 $\\alpha_1=\\begin{pmatrix}k_1\\\\k_1\\\\0\\end{pmatrix}$。\n\n将 $\\alpha_1=\\begin{pmatrix}k_1\\\\k_1\\\\0\\end{pmatrix}$ 代入方程 $A\\alpha_2=2\\alpha_1+4\\alpha_2$，由 $(A-4E)\\alpha_2=2\\alpha_1$，解得 $\\alpha_2=\\begin{pmatrix}2k_1+k_2\\\\k_2\\\\0\\end{pmatrix}$。\n\n$A\\alpha_3=2\\alpha_3\\rightarrow(A-2E)\\alpha_3=0$，$A-2E=\\begin{pmatrix}3&-1&0\\\\1&1&0\\\\0&0&0\\end{pmatrix}$，解得 $\\alpha_3=\\begin{pmatrix}0\\\\0\\\\k_3\\end{pmatrix}$。\n\n则 $P=\\begin{pmatrix}k_1&2k_1+k_2&0\\\\k_1&k_2&0\\\\0&0&k_3\\end{pmatrix}$，要满足 $P$ 可逆，即\n$$|P|=\\begin{vmatrix}k_1&2k_1+k_2&0\\\\k_1&k_2&0\\\\0&0&k_3\\end{vmatrix}=-2k_1^2k_3\\neq0,$$\n\n当 $a=1$ 时，存在 $P=\\begin{pmatrix}k_1&2k_1+k_2&0\\\\k_1&k_2&0\\\\0&0&k_3\\end{pmatrix}$，其中 $k_1\\neq0,k_3\\neq0$，使得 $P^{-1}AP=B$。……4 分\n\n（注：本题只需要找到一个满足的矩阵即可，可用咱们这里的通用形式验证，批改过程中根据计算过程酌情给分）"),
  Q(6, "高数", "偏导数定义与连续", "中档", 3,
    "设 $f(x,y)=g(x,y)\\left|x-y\\right|$，其中 $g(x,y)$ 在 $(0,0)$ 的某邻域内连续，则“$g(0,0)=0$”是“$f_x'(0,0)$ 和 $f_y'(0,0)$ 存在”的（　　）.",
    ["充分非必要条件", "必要非充分条件", "充分必要条件", "既非充分也非必要条件"], "C",
    "若 $g(0,0)=0$，则 $\\lim_{x\\to 0}\\frac{f(x,0)-f(0,0)}{x}=\\lim_{x\\to 0}\\frac{g(x,0)\\cdot|x|}{x}=0$，即 $f_x'(0,0)=0$；同理 $\\lim_{y\\to 0}\\frac{f(0,y)-f(0,0)}{y}=\\lim_{y\\to 0}\\frac{g(0,y)\\cdot|y|}{y}=0$，即 $f_y'(0,0)=0$。反之，若两个偏导极限存在，则满足 $\\lim_{x\\to 0^+}g(x,0)\\frac{|x|}{x}=\\lim_{x\\to 0^-}g(x,0)\\frac{|x|}{x}$，$\\lim_{y\\to 0^+}g(0,y)\\frac{|y|}{y}=\\lim_{y\\to 0^-}g(0,y)\\frac{|y|}{y}$，可得 $g(0,0)=-g(0,0)$，即 $g(0,0)=0$。因此 $f_x'(0,0)$、$f_y'(0,0)$ 存在的充要条件是 $g(0,0)=0$，选 (C)。"),
  Q(7, "高数", "定积分性质", "常规", 2,
    "设 $f(t)$ 为连续函数，$a$ 是常数，则下列结论中正确的是（　　）.",
    ["若 $f(t)$ 为偶函数，则 $\\displaystyle\\int_0^x dy\\int_a^y f(t)dt$ 为奇函数", "若 $f(t)$ 为奇函数，则 $\\displaystyle\\int_a^x dy\\int_0^y f(t)dt$ 为奇函数", "若 $f(t)$ 为偶函数，则 $\\displaystyle\\int_0^x dy\\int_0^y f(t)dt$ 为奇函数", "若 $f(t)$ 为奇函数，则 $\\displaystyle\\int_0^x dy\\int_y^x f(t)dt$ 为奇函数"], "D",
    "【法一】设 $F(t)$ 是 $f(t)$ 的一个原函数，则 $f(t)$ 是奇函数时 $F(t)$ 必为偶函数。对于 (D)，$\\int_0^x dy\\int_y^x f(t)dt=\\int_0^x[F(x)-F(y)]dy=xF(x)-\\int_0^x F(y)dy$，而 $xF(x)$ 及 $\\int_0^x F(y)dy$ 均为奇函数，故 (D) 正确。【法二】取 $f(t)=t$，则 $\\int_a^x dy\\int_0^y f(t)dt=\\int_0^x\\frac{1}{2}y^2dy=\\frac{1}{6}x^3-\\frac{1}{6}a^3$，在 $a\\neq 0$ 时非奇非偶，排除 (B)；取 $f(t)=1$，则 $\\int_0^x dy\\int_a^y f(t)dt=\\int_0^x(y-a)dy=\\frac{1}{2}x^2-ax$ 不是奇函数，排除 (A)；$f(t)$ 为偶函数时，$\\int_0^y f(t)dt$ 是奇函数，$\\int_0^x dy\\int_0^y f(t)dt$ 为偶函数，排除 (C)。故选 (D)。"),
  Q(8, "线代", "二次型惯性指数", "中档", 3,
    "设二次型 $f(x_1,x_2,x_3)=(x_1+kx_2)^2+(x_1+x_3)^2-\\left[x_1-2x_2+(k+2)x_3\\right]^2$ 的负惯性指数为 $0$，则 $k=$（　　）.",
    ["$-1$", "1", "$-2$", "2"], "C",
    "作换元 $y_1=x_1+kx_2$，$y_2=x_1+x_3$，$y_3=x_1-2x_2+(k+2)x_3$，即 $y=Px=\\begin{pmatrix}1&k&0\\\\1&0&1\\\\1&-2&k+2\\end{pmatrix}x$。① 若 $|P|\\neq 0$，$P$ 可逆时标准型为 $f=y_1^2+y_2^2-y_3^2$，不满足要求；② 若 $|P|=0$，则 $|P|=-(k+2)(k-1)=0$，$k=1,-2$。当 $k=1$ 时，$f=(x_1+x_2)^2+(x_1+x_3)^2-(x_1-2x_2+3x_3)^2$，取 $x_1=0,x_2=0,x_3=1$，此时 $f(0,0,1)=-8<0$，不满足要求；当 $k=-2$ 时，$f=(x_1+x_3)^2\\ge 0$ 满足要求，故 $k=-2$，选 (C)。"),
  Q(9, "线代", "线性方程组解的结构", "中档", 3,
    "设 $A,B$ 为 $n$ 阶矩阵，且方程组 $Ax=0$ 与方程组 $Bx=0$ 有非零公共解，则下列选项中不成立的是（　　）.",
    ["方程组 $\\begin{pmatrix}O & A^TA\\\\ A^T & E\\end{pmatrix}x=0$ 与方程组 $\\begin{pmatrix}A^T & E\\\\ O & A\\end{pmatrix}x=0$ 有非零公共解", "方程组 $\\begin{pmatrix}E & A\\\\ O & AB\\end{pmatrix}x=0$ 与方程组 $\\begin{pmatrix}E & AB\\\\ O & B\\end{pmatrix}x=0$ 有非零公共解", "方程组 $\\begin{pmatrix}A & AA^T\\\\ O & A^TA\\end{pmatrix}x=0$ 与方程组 $\\begin{pmatrix}A & O\\\\ A^TA & AA^T\\end{pmatrix}x=0$ 同解", "方程组 $\\begin{pmatrix}A & AB\\\\ O & E\\end{pmatrix}x=0$ 与方程组 $\\begin{pmatrix}O & E\\\\ A & BA\\end{pmatrix}x=0$ 同解"], "C",
    "由 $Ax=0$ 与 $Bx=0$ 有非零公共解，得 $r\\binom{A}{B}<n$，$r(A)<n$，$r(B)<n$。对于 (A)，对矩阵作初等行变换可化为 $\\begin{pmatrix}O&O\\\\O&O\\\\A^T&E\\\\-AA^T&O\\end{pmatrix}$，所以 $r=n+r(-AA^T)=n+r(A)<2n$，故两方程组有非零公共解，(A) 正确。对于 (B)，变换可得 $r\\begin{pmatrix}E&O\\\\O&O\\\\O&A\\\\O&B\\end{pmatrix}=n+r\\binom{A}{B}<2n$，故有非零公共解，(B) 正确。对于 (C)，$r\\binom{A\\ AA^T}{O\\ A^TA}=r(A)+r(A^TA)=2r(A)$；而 $r\\binom{A\\ O}{A^TA\\ AA^T}=r(A)+r\\binom{AA^T}{A^TA}$（变换后为 $\\begin{pmatrix}O&AA^T\\\\O&A^TA\\\\A&O\\\\A^TA&AA^T\\end{pmatrix}$ 型），此秩与 $2r(A)$ 不一定相等，故 (C) 错误。对于 (D)，$\\binom{A\\ AB}{O\\ E}\\xrightarrow{c_2-c_1B}\\binom{A\\ O}{O\\ E}$，$r=r(A)+n$；$\\binom{O\\ E}{A\\ BA}\\xrightarrow{c_2-Bc_1}\\binom{O\\ E}{A\\ O}$，$r=r(A)+n$；进一步行变换可得 $r\\binom{A\\ AB}{O\\ E\\\\O\\ E\\\\A\\ BA}=r(A)+n$ 与两者均相等，故两方程组同解，(D) 正确。综上选 (C)。"),
  Q(10, "线代", "实对称矩阵与合同相似", "难题", 4,
    "若矩阵 $A,B$ 均为三阶实对称矩阵，且矩阵 $A,B$ 可逆，则下列四个命题中成立的个数是（　　）.\n① 存在可逆矩阵 $P$，使得 $P^TAP=B$.\n② 存在可逆矩阵 $P$，使得 $A^2=P^TP$.\n③ 存在可逆矩阵 $P$，使得 $P^TA^2P=B^2$.\n④ 存在可逆矩阵 $P$，使得 $P^{-1}ABP=BA$.",
    ["1", "2", "3", "4"], "C",
    "① 仅有 $A,B$ 可逆，但特征值正负性不一定相同，故 $A,B$ 不一定合同，命题①错误。② $A$ 可逆，$\\lambda(A^2)=\\lambda_1^2,\\lambda_2^2,\\lambda_3^2>0$，故 $A^2$ 与 $E$ 合同，必存在可逆矩阵 $Q$ 使 $Q^TA^2Q=E$，即 $A^2=(Q^{-1})^T(Q^{-1})$，取 $P=Q^{-1}$，则 $A^2=P^TP$，命题②正确。③ $A^2$ 的特征值均大于 0，同理 $B^2$ 的特征值均大于 0，故 $A^2$ 与 $B^2$ 合同，即存在可逆矩阵 $P$ 使 $P^TA^2P=B^2$，命题③正确。④ 若 $P=A$，则 $P^{-1}ABP=BA$，命题④正确。因此成立的个数为 3，选 (C)。"),
  Q(11, "高数", "幂指函数极限", "中档", 3,
    "$\\displaystyle\\lim_{x\\to+\\infty}\\left(\\frac{x^{\\frac{1}{x}}+1}{2}\\right)^{\\frac{x}{\\ln x}}=$ ________.",
    null, "e^{\\frac{1}{2}}",
    "$\\lim_{x\\to+\\infty}\\left(\\frac{x^{\\frac{1}{x}}+1}{2}\\right)^{\\frac{x}{\\ln x}}=e^{\\lim_{x\\to+\\infty}\\frac{x}{\\ln x}\\cdot\\ln\\left(\\frac{x^{\\frac{1}{x}}+1}{2}\\right)}$，其中 $x^{\\frac{1}{x}}\\to 1$，$\\ln\\left(\\frac{x^{1/x}+1}{2}\\right)\\sim\\frac{1}{2}(x^{1/x}-1)\\sim\\frac{1}{2}\\cdot\\frac{\\ln x}{x}$，故指数极限为 $\\frac{1}{2}$，极限为 $e^{\\frac{1}{2}}$。"),
  Q(12, "高数", "隐函数求导", "中档", 3,
    "设函数 $y=y(x)$ 可由方程 $xy+\\displaystyle\\int_0^{xy}e^{t^2}dt+1=x+e^{y}$ 确定，则 $\\left.\\dfrac{dy}{dx}\\right|_{x=0}=$ ________.",
    null, "-1",
    "当 $x=0$ 时，由原方程得 $y(0)=0$。在方程 $xy+\\int_0^{xy}e^{t^2}dt+1=x+e^y$ 两边对 $x$ 求导，得 $y+xy'+e^{x^2y^2}\\cdot(y+xy')=1+e^y y'$，代入 $x=0, y(0)=0$，得 $y'(0)=-1$。"),
  Q(13, "高数", "参数方程与定积分", "中档", 3,
    "若函数 $y=y(x)$ 由参数方程 $\\begin{cases}x=2t+\\sin t,\\\\ y=\\ln\\left(\\sin t+e^t\\right)\\end{cases}$ 确定，则 $\\displaystyle\\int_0^{2\\pi}(2\\pi-x)y'(x)dx=$ ________.",
    null, "-\\frac{\\pi}{3}",
    "分部积分：$\\int_0^{2\\pi}(2\\pi-x)y''(x)dx=(2\\pi-x)y'(x)\\big|_0^{2\\pi}+\\int_0^{2\\pi}y'(x)dx=-2\\pi y'(0)+y(2\\pi)-y(0)$。由 $x=2t+\\sin t$，$\\frac{dx}{dt}=2+\\cos t>0$，故 $x(t)$ 单调递增，$t=0$ 时 $x=0$，$t=\\pi$ 时 $x=2\\pi$。所以 $y(2\\pi)=\\ln(\\sin t+e^t)\\big|_{t=\\pi}=\\pi$，$y(0)=\\ln(\\sin t+e^t)\\big|_{t=0}=0$，$y'(0)=\\left.\\frac{dy}{dx}\\right|_{t=0}=\\left.\\left(\\frac{\\cos t+e^t}{\\sin t+e^t}\\cdot\\frac{1}{2+\\cos t}\\right)\\right|_{t=0}=\\frac{2}{3}$。综上，$\\int_0^{2\\pi}(2\\pi-x)y''(x)dx=-\\frac{4\\pi}{3}+\\pi=-\\frac{\\pi}{3}$。"),
  Q(14, "高数", "极坐标图形面积", "中档", 3,
    "极坐标曲线 $r=1+\\cos\\theta$ 与 $r=1$ 围成的公共部分的区域面积为______.",
    null, "\\frac{5\\pi}{4}-2",
    "由 $1+\\cos\\theta=1$ 得 $\\theta=\\frac{\\pi}{2},\\frac{3\\pi}{2}$。$S=\\frac{1}{2}\\int_{\\frac{\\pi}{2}}^{\\frac{\\pi}{2}}1\\,d\\theta+\\frac{1}{2}\\int_{\\frac{\\pi}{2}}^{\\frac{3\\pi}{2}}(1+\\cos\\theta)^2d\\theta=\\frac{\\pi}{2}+\\frac{1}{2}\\int_{\\frac{\\pi}{2}}^{\\frac{3\\pi}{2}}(1+2\\cos\\theta+\\cos^2\\theta)d\\theta=\\frac{\\pi}{2}+\\frac{1}{2}\\left(\\frac{3\\pi}{2}-4\\right)=\\frac{5\\pi}{4}-2$。"),
  Q(15, "高数", "多元函数最值与不等式", "中档", 3,
    "若对于任意实数 $a,b$，不等式 $a^4+b^4-(a+b)^2\\ge A$ 恒成立，则 $A$ 的取值范围为__________.",
    null, "(-\\infty,-2]",
    "转化为求 $f(x,y)=x^4+y^4-(x+y)^2$ 的最小值。$\\frac{\\partial f}{\\partial x}=4x^3-2x-2y$，$\\frac{\\partial f}{\\partial y}=4y^3-2x-2y$。令两式为 $0$，两式相减得 $x^3-y^3=0$，从而 $x=y$，代入得 $x^3-x=0$，解得 $x=0,\\pm1$，驻点为 $(0,0),(1,1),(-1,-1)$。二阶偏导：$\\frac{\\partial^2 f}{\\partial x^2}=12x^2-2$，$\\frac{\\partial^2 f}{\\partial x\\partial y}=-2$，$\\frac{\\partial^2 f}{\\partial y^2}=12y^2-2$。当 $x=\\pm1,y=\\pm1$ 时 $AC-B^2=96>0$ 且 $A=10>0$，$(1,1),(-1,-1)$ 为极小值点，极小值 $f(1,1)=f(-1,-1)=-2$。而 $x\\to\\infty$ 或 $y\\to\\infty$ 时 $f\\to\\infty$，故最小值为 $-2$，即 $f(x,y)\\ge-2$，所以 $A\\le-2$。"),
  Q(16, "线代", "矩阵秩与行列式", "中档", 3,
    "矩阵 $A,B$ 均为三阶矩阵，其中矩阵 $A$ 不可逆，矩阵 $B$ 满足 $(A+E)B=O$，$r(B)=2$，则 $|A+2E|=$ ______.",
    null, "2",
    "矩阵 $A$ 不可逆，故存在特征值 $0$。由 $(A+E)B=O$ 得 $AB=-B$，记 $B=(\\alpha_1,\\alpha_2,\\alpha_3)$，则 $A(\\alpha_1,\\alpha_2,\\alpha_3)=-(\\alpha_1,\\alpha_2,\\alpha_3)$，即 $B$ 的每一非零列向量均为 $A$ 对应特征值 $-1$ 的特征向量，又 $r(B)=2$，故特征值 $-1$ 对应两个线性无关的特征向量，$-1$ 至少是 $A$ 的二重特征值。于是 $\\lambda(A)=0,-1,-1$，故 $\\lambda(A+2E)=2,1,1$，$|A+2E|=2$。"),
  Q(17, "高数", "二重积分与对称性", "中档", 3,
    "设区域 $D=\\left\\{(x,y)\\big|x^2+y^2\\le 1, x+y\\ge 0\\right\\}$，计算二重积分 $\\displaystyle\\iint_D\\frac{xy^2}{1+x^2+y^2}dxdy$.",
    null, "\\frac{\\sqrt{2}\\pi}{24}-\\frac{\\sqrt{2}}{9}",
    "用直线 $y=x$ 将 $D$ 分割为 $D_1,D_2$，$\\iint_D\\frac{xy^2}{1+x^2+y^2}dxdy=\\iint_{D_1}+\\iint_{D_2}$。由于 $D_2$ 关于 $y$ 轴对称，$\\iint_{D_2}\\frac{xy^2}{1+x^2+y^2}dxdy=0$。对 $D_1$ 用极坐标：$\\iint_D\\frac{xy^2}{1+x^2+y^2}dxdy=2\\int_0^{\\frac{\\pi}{4}}d\\theta\\int_0^1\\frac{r^3\\cos\\theta\\sin^2\\theta}{1+r^2}r\\,dr=2\\int_0^{\\frac{\\pi}{4}}\\cos\\theta\\sin^2\\theta d\\theta\\int_0^1\\frac{r^4}{1+r^2}dr=\\frac{\\sqrt{2}\\pi}{24}-\\frac{\\sqrt{2}}{9}$。"),
  Q(18, "高数", "导数定义与切线方程", "难题", 4,
    "设连续的奇函数 $y=f(x)$ 在 $x=1$ 处可导，且在 $x=0$ 的去心邻域内满足等式\n$$2f(x)+f(-x)=\\frac{\\sqrt{1+2f\\left(e^x\\right)}-\\sqrt{1-f(1-\\tan x)}}{x}-1.$$\n试求 $y=f(x)$ 在 $x=-1$ 处的切线方程.",
    null, "y=2x+2",
    "两边取极限，由 $f$ 连续得 $\\lim_{x\\to0}[2f(x)+f(-x)]=3f(0)=0$，则 $\\lim_{x\\to0}\\frac{\\sqrt{1+2f(e^x)}-\\sqrt{1-f(1-\\tan x)}}{x}=1$，且 $\\lim_{x\\to0}[\\sqrt{1+2f(e^x)}-\\sqrt{1-f(1-\\tan x)}]=\\sqrt{1+2f(1)}-\\sqrt{1-f(1)}=0$，可得 $f(1)=0$。分子有理化：$\\lim_{x\\to0}\\frac{\\sqrt{1+2f(e^x)}-\\sqrt{1-f(1-\\tan x)}}{x}=\\lim_{x\\to0}\\frac{2f(e^x)+f(1-\\tan x)}{2x}=\\lim_{x\\to0}\\left[\\frac{f(e^x)-f(1)}{e^x-1}\\cdot\\frac{e^x-1}{x}+\\frac{f(1-\\tan x)-f(1)}{-\\tan x}\\cdot\\frac{-\\tan x}{2x}\\right]=f'(1)-\\frac{1}{2}f'(1)=\\frac{1}{2}f'(1)=1$，所以 $f'(1)=2$。（注：本题不能使用洛必达，使用洛必达直接扣 6 分）由奇函数，$f(-1)=-f(1)=0$，$f'(-1)=f'(1)=2$，故切线方程为 $y=2x+2$。"),
  Q(19, "高数", "二阶偏导数与变量代换", "难题", 4,
    "设二元函数 $z=z(x,y)$ 具有二阶连续偏导数，且满足 $2\\dfrac{\\partial^2 z}{\\partial x^2}-3\\dfrac{\\partial^2 z}{\\partial x\\partial y}-2\\dfrac{\\partial^2 z}{\\partial y^2}=25e^{3x-y}$. 作变量代换 $u=2x+y$，$v=x-2y$，记 $z(x,y)=f(u,v)$.\n(1) 求 $\\dfrac{\\partial^2 f}{\\partial u\\partial v}$；\n(2) 若 $\\dfrac{\\partial f(u,0)}{\\partial u}=e^u+2u$，$f(0,v)=e^v+v^2+1$，求 $z(x,y)$ 的表达式.",
    null, "(1) $\\dfrac{\\partial^2 f}{\\partial u\\partial v}=e^{u+v}$；(2) $z(x,y)=e^{3x-y}+5x^2+5y^2+1$",
    "(1) 由复合函数求导法则，得 $\\frac{\\partial z}{\\partial x}=2f_u+f_v$，$\\frac{\\partial z}{\\partial y}=f_u-2f_v$，则 $\\frac{\\partial^2 z}{\\partial x^2}=4f_{uu}+4f_{uv}+f_{vv}$，$\\frac{\\partial^2 z}{\\partial x\\partial y}=2f_{uu}-3f_{uv}-2f_{vv}$，$\\frac{\\partial^2 z}{\\partial y^2}=f_{uu}-4f_{uv}+4f_{vv}$。代入原方程，得 $25f_{uv}=25e^{u+v}$，故 $\\frac{\\partial^2 f}{\\partial u\\partial v}=e^{u+v}$。(2) 由 (1) 知 $f_{uv}=e^{u+v}$，对 $v$ 积分得 $f_u=e^{u+v}+C(u)$。令 $v=0$，由 $f_u(u,0)=e^u+2u$，得 $C(u)=2u$，所以 $f_u=e^{u+v}+2u$。对 $u$ 积分得 $f(u,v)=e^{u+v}+u^2+C(v)$。令 $u=0$，由 $f(0,v)=e^v+v^2+1$，得 $C(v)=v^2+1$，所以 $f(u,v)=e^{u+v}+u^2+v^2+1$。将 $u=2x+y$，$v=x-2y$ 代入，得 $z(x,y)=e^{3x-y}+(2x+y)^2+(x-2y)^2+1$，化简可得 $z(x,y)=e^{3x-y}+5x^2+5y^2+1$。"),
  Q(20, "高数", "微分方程与形心", "中档", 3,
    "设函数 $f(x)$ 和 $g(x)$ 可导，且满足 $f'(x)=\\dfrac{1}{2}g(x), g'(x)=\\dfrac{1}{2}f(x)$，$f(0)=2, f'(0)=0$.\n(1) 求 $y=f(x)$ 的表达式.\n(2) 求区间 $[0,2]$ 内曲线 $y=f(x)$ 的形心坐标.",
    null, "(1) $f(x)=e^{\\frac{x}{2}}+e^{-\\frac{x}{2}}$；(2) 形心坐标为 $\\left(\\dfrac{4}{e+1},\\ \\dfrac{e}{2}+\\dfrac{1}{2e}+\\dfrac{2e}{e^2-1}\\right)$",
    "(1) 由 $f'(x)=\\frac{1}{2}g(x)$，$g'(x)=\\frac{1}{2}f(x)$，得 $f''(x)=\\frac{1}{4}f(x)$，即 $f''(x)-\\frac{1}{4}f(x)=0$，解得 $f(x)=C_1e^{\\frac{x}{2}}+C_2e^{-\\frac{x}{2}}$。由 $f(0)=2, f'(0)=0$ 可知 $\\begin{cases}C_1+C_2=2\\\\C_1-C_2=0\\end{cases}$，所以 $C_1=C_2=1$，从而 $f(x)=e^{\\frac{x}{2}}+e^{-\\frac{x}{2}}$。(2) 由形心公式，形心坐标为 $\\left(\\bar x,\\bar y\\right)=\\left(\\frac{\\int_0^2 x\\,ds}{\\int_0^2 ds},\\frac{\\int_0^2 y\\,ds}{\\int_0^2 ds}\\right)$。$ds=\\sqrt{1+(y')^2}=\\frac{1}{2}e^{\\frac{x}{2}}+\\frac{1}{2}e^{-\\frac{x}{2}}$，$\\int_0^2 ds=e-\\frac{1}{e}$；$\\int_0^2 x\\,ds\\xlongequal{t=\\frac{x}{2}}2\\int_0^1 t(e^t+e^{-t})dt=2t(e^t-e^{-t})\\Big|_0^1-2\\int_0^1(e^t-e^{-t})dt=2\\left(e-\\frac{1}{e}\\right)-2\\left(e+\\frac{1}{e}\\right)+4=4-\\frac{4}{e}$；$\\int_0^2 y\\,ds=\\int_0^2\\left(e^{\\frac{x}{2}}+e^{-\\frac{x}{2}}\\right)\\left(\\frac{1}{2}e^{\\frac{x}{2}}+\\frac{1}{2}e^{-\\frac{x}{2}}\\right)dx=\\int_0^2\\left(\\frac{1}{2}e^x+\\frac{1}{2}e^{-x}+1\\right)dx=\\frac{e^2}{2}-\\frac{1}{2e^2}+2$。故 $\\bar x=\\frac{4-\\frac{4}{e}}{e-\\frac{1}{e}}=\\frac{4}{e+1}$，$\\bar y=\\frac{\\frac{e^2}{2}-\\frac{1}{2e^2}+2}{e-\\frac{1}{e}}=\\frac{e}{2}+\\frac{1}{2e}+\\frac{2e}{e^2-1}$，形心坐标为 $\\left(\\frac{4}{e+1},\\frac{e}{2}+\\frac{1}{2e}+\\frac{2e}{e^2-1}\\right)$。"),
  Q(21, "高数", "数列极限与单调有界", "难题", 4,
    "若数列 $\\{x_n\\}$ 满足 $x_{n+1}=1+\\ln\\left(\\dfrac{x_n^2}{1+\\ln x_n}\\right)$，其中 $n=1,2,\\ldots$，且 $x_1=a>1$.\n(1) 证明：对于任意的正整数 $n$，都有 $x_n>1$.\n(2) 证明数列 $\\{x_n\\}$ 收敛，并计算 $\\displaystyle\\lim_{n\\to\\infty}x_n$.",
    null, "$\\lim_{n\\to\\infty}x_n=1$",
    "(1) 记 $f(x)=x^2-1-\\ln x, x\\ge1$，则 $f'(x)=2x-\\frac{1}{x}>0$，$f(x)$ 在 $[1,+\\infty)$ 上单调递增，因此当 $x\\ge1$ 时 $f(x)>f(1)=0$，即 $x>1$ 时 $x^2>1+\\ln x$。因此当 $x_1=a>1$ 时，$x_1^2-1-\\ln x_1>0$，即 $\\frac{x_1^2}{1+\\ln x_1}>1$，$\\ln\\left(\\frac{x_n^2}{1+\\ln x_n}\\right)>0$，$x_2=1+\\ln\\left(\\frac{x_1^2}{1+\\ln x_1}\\right)>1$。根据数学归纳法，当 $n=k$ 时若 $x_k>1$ 成立，则当 $n=k+1$ 时，由 $\\frac{x_k^2}{1+\\ln x_k}>1$，均可得 $x_{k+1}>1$ 成立。综上所述 $x_n>1$，即数列 $\\{x_n\\}$ 有下界。(2) 由 $x_{n+1}-x_n=1+\\ln\\left(\\frac{x_n^2}{1+\\ln x_n}\\right)-x_n=1+2\\ln x_n-\\ln(1+\\ln x_n)-x_n$。记 $g(x)=1+2\\ln x-\\ln(1+\\ln x)-x$，$x>1$，则 $g'(x)=\\frac{1+2\\ln x-x-x\\ln x}{x(1+\\ln x)}$。再令 $\\varphi(x)=1+2\\ln x-x-x\\ln x$，则 $\\varphi'(x)=\\frac{2}{x}-2-\\ln x$，当 $x>1$ 时 $\\varphi'(x)<0$，$\\varphi(x)$ 单调递减，所以此时 $\\varphi(x)<\\varphi(1)=0$。又 $g'(x)=\\frac{\\varphi(x)}{x(1+\\ln x)}$，所以当 $x>1$ 时 $g'(x)<0$，$g(x)$ 单调递减，此时 $g(x)<g(1)=0$。综上所述，当 $x_n>1$ 时 $x_{n+1}-x_n=g(x_n)<0$，数列 $\\{x_n\\}$ 单调递减。由单调有界原则，数列 $\\{x_n\\}$ 单调递减且有下界，数列 $\\{x_n\\}$ 收敛。记 $A=\\lim_{n\\to\\infty}x_n$，则 $\\lim_{n\\to\\infty}x_{n+1}=A$，对等式两侧取极限可得 $A=1+\\ln\\left(\\frac{A^2}{1+\\ln A}\\right)$，解得 $A=1$，所以 $\\lim_{n\\to\\infty}x_n=1$。"),
  Q(22, "线代", "矩阵相似对角化", "难题", 4,
    "若矩阵 $A=\\begin{pmatrix}5 & -a & 0\\\\ 1 & a+2 & 0\\\\ 0 & 0 & 2\\end{pmatrix}$ 不可相似对角化，其中 $a$ 为参数.\n(1) 计算 $a$ 的取值；\n(2) 判断是否存在可逆矩阵 $P$，使得 $P^{-1}AP=B$，其中 $B=\\begin{pmatrix}2a+2 & 2 & 0\\\\ 0 & 2a+2 & 0\\\\ 0 & 0 & 2\\end{pmatrix}$. 若不存在，说明理由；若存在，试找出一个满足的可逆矩阵 $P$.",
    null, "(1) $a=1$ 或 $a=9$；(2) $a=9$ 时不存在；$a=1$ 时存在可逆矩阵 $P$ 使 $P^{-1}AP=B$（$P$ 由方程组 $A\\alpha_1=4\\alpha_1$，$A\\alpha_2=2\\alpha_1+4\\alpha_2$，$A\\alpha_3=2\\alpha_3$ 的解构成）",
    "(1) $|A-\\lambda E|=(2-\\lambda)\\left[\\lambda^2-(a+7)\\lambda+6a+10\\right]$。由于 $A$ 不可相似对角化，则 $A$ 必定存在多重特征值，分类讨论：① 若 $\\lambda=2$ 为三重特征值，则 $a+7=4, 6a+10=4$，无解，不可能。② 若 $\\lambda=2$ 为二重特征值，则 $\\lambda=2$ 也为 $\\lambda^2-(a+7)\\lambda+6a+10=0$ 的根，代入可得 $a=0$；当 $a=0$ 时，$A-2E=\\begin{pmatrix}3&0&0\\\\1&0&0\\\\0&0&0\\end{pmatrix}$，$r(A-2E)=1$，$\\lambda=2$ 对应两个线性无关的特征向量，此时 $A$ 能相似对角化，不满足。③ 若 $\\lambda^2-(a+7)\\lambda+6a+10=0$ 出现二重特征值，$\\Delta=(a+7)^2-4(6a+10)=(a-1)(a-9)=0$，即 $a=1$ 或 $a=9$。当 $a=1$ 时，$\\lambda^2-(a+7)\\lambda+6a+10=(\\lambda-4)^2$，$\\lambda=4$ 为二重特征值，$A-4E=\\begin{pmatrix}1&-1&0\\\\1&-1&0\\\\0&0&-2\\end{pmatrix}$，$r(A-4E)=2$，$\\lambda=4$ 对应只有一个线性无关的特征向量，此时 $A$ 不能相似对角化，满足。当 $a=9$ 时，$\\lambda^2-(a+7)\\lambda+6a+10=(\\lambda-8)^2$，$\\lambda=8$ 为二重特征值，$A-8E=\\begin{pmatrix}-3&-9&0\\\\1&3&0\\\\0&0&-6\\end{pmatrix}$，$r(A-8E)=2$，$\\lambda=8$ 对应只有一个线性无关的特征向量，此时 $A$ 不能相似对角化，满足。综上 $a=1$ 或 $a=9$。(2) 当 $a=9$ 时，$B=\\begin{pmatrix}20&2&0\\\\0&20&0\\\\0&0&2\\end{pmatrix}$，特征值为 $20,20,2$ 与矩阵 $A$ 的特征值不同，故 $a=9$ 时矩阵 $A$ 必定不可能相似于矩阵 $B$。当 $a=1$ 时，$B=\\begin{pmatrix}4&2&0\\\\0&4&0\\\\0&0&2\\end{pmatrix}$，矩阵 $A$ 可能与 $B$ 相似，不妨假设存在 $P=(\\alpha_1,\\alpha_2,\\alpha_3)$ 满足 $P^{-1}AP=B$，则 $AP=BP$，$A(\\alpha_1,\\alpha_2,\\alpha_3)=(4\\alpha_1,\\,2\\alpha_1+4\\alpha_2,\\,2\\alpha_3)$，说明方程组 $\\begin{cases}A\\alpha_1=4\\alpha_1\\\\A\\alpha_2=2\\alpha_1+4\\alpha_2\\\\A\\alpha_3=2\\alpha_3\\end{cases}$ 有解。接下来对方程组求解，计算 $\\alpha_1,\\alpha_2,\\alpha_3$（求解过程接后页）。"),
];

/* 崔命六套卷（数三）· 卷二 · 伪年份 3423-3 · 22 题 */
PAPERS['3423-3'] = [
  Q(1, "高数", "间断点分类", "中档", 3,
    "函数 $f(x)=\\dfrac{\\ln\\left|x^2-1\\right|\\sin(x+1)}{x^2}\\cdot e^{\\frac{1}{x}}$ 的可去间断点个数是（　　）.",
    ["0", "1", "2", "3"], "C",
    "函数 $f(x)$ 在 $x=0,\\pm 1$ 处无定义，$x=0,\\pm1$ 为间断点。计算极限：$\\lim_{x\\to -1}\\frac{\\ln|x^2-1|\\sin(x+1)}{x^2}e^{-\\frac{1}{|x|}}=0$，$\\lim_{x\\to 0}\\frac{\\ln|x^2-1|\\sin(x+1)}{x^2}e^{-\\frac{1}{|x|}}=0$，$\\lim_{x\\to 1}\\frac{\\ln|x^2-1|\\sin(x+1)}{x^2}e^{-\\frac{1}{|x|}}=\\infty$。故 $x=0,-1$ 为 $f(x)$ 的可去间断点，共 2 个，答案选 (C)。"),
  Q(2, "高数", "分段函数可导性", "中档", 3,
    "若函数 $f(x)=\\begin{cases}ax^2+b\\sin x+c, & x\\le 0,\\\\ \\ln(1+x), & x>0,\\end{cases}$ 在 $x=0$ 处一阶导函数连续但二阶导数不存在，则 $a,b,c$ 满足（　　）.",
    ["$a\\ne-\\dfrac{1}{2},b=1,c=0$", "$a\\ne\\dfrac{1}{2},b=0,c=0$", "$a=-\\dfrac{1}{2},b=1,c=0$", "$a=-\\dfrac{1}{2},b=0,c=1$"], "A",
    "因 $f(0^-)=c,\\ f(0^+)=0,\\ f(0)=c$，又 $f(x)$ 在 $x=0$ 连续，所以 $c=0$。由 $f'_-(0)=\\lim_{x\\to 0^-}\\frac{ax^2+b\\sin x-0}{x}=b$，$f'_+(0)=\\lim_{x\\to 0^+}\\frac{\\ln(1+x)-0}{x}=1$，所以 $b=1$ 时 $f'(0^-)=f'(0^+)=f'(0)=1$，$f'(x)$ 在 $x=0$ 处连续且 $f'(x)=\\begin{cases}2ax+\\cos x,&x<0,\\\\1,&x=0,\\\\\\frac{1}{1+x},&x>0.\\end{cases}$ 又 $f''(0)=\\lim_{x\\to 0}\\frac{f'(x)-f'(0)}{x}=\\begin{cases}\\lim_{x\\to 0^-}\\frac{2ax+\\cos x-1}{x}=2a,\\\\ \\lim_{x\\to 0^+}\\frac{\\frac{1}{1+x}-1}{x}=\\lim_{x\\to 0^+}\\frac{-x}{x(1+x)}=-1,\\end{cases}$ 当 $2a\\neq -1$ 即 $a\\neq -\\frac{1}{2}$ 时，$f(x)$ 在 $x=0$ 处二阶不可导。综上 $a\\neq -\\frac{1}{2}, b=1, c=0$，答案选 (A)。"),
  Q(3, "高数", "齐次微分方程变换", "难题", 4,
    "若微分方程 $y'=ax^{\\alpha}+by^{\\beta}\\ (\\alpha\\beta\\ne 0, ab\\ne 0)$ 经变换 $y=z^m$ 可化为一阶齐次方程 $\\dfrac{dz}{dx}=f\\left(\\dfrac{z}{x}\\right)$，则常数 $\\alpha,\\beta$ 满足（　　）.",
    ["$\\dfrac{1}{\\beta}-\\dfrac{1}{\\alpha}=1$", "$\\dfrac{1}{\\alpha}-\\dfrac{1}{\\beta}=1$", "$\\dfrac{1}{\\beta}+\\dfrac{1}{\\alpha}=1$", "$\\dfrac{1}{\\beta}-\\dfrac{1}{\\alpha}=0$"], "A",
    "将 $\\frac{dy}{dx}=mz^{m-1}\\frac{dz}{dx}$ 代入得 $mz^{m-1}\\frac{dz}{dx}=ax^{\\alpha}+bz^{\\beta m}$，即 $m\\frac{dz}{dx}=a\\frac{x^{\\alpha}}{z^{m-1}}+bz^{\\beta m-m+1}$。要使此方程为齐次方程，则应有 $\\begin{cases}\\alpha=m-1,\\\\ \\beta m-m+1=0,\\end{cases}$ 消去 $m$ 有 $\\alpha\\beta-\\alpha+\\beta=0$，即 $\\frac{1}{\\beta}-\\frac{1}{\\alpha}=1$，故答案选 (A)。"),
  Q(4, "高数", "偏导数定义", "中档", 3,
    "设 $f(x,y)=g(x,y)\\left|x-y\\right|$，其中 $g(x,y)$ 在 $(0,0)$ 的某邻域内连续，则“$g(0,0)=0$”是“$f_x'(0,0)$ 和 $f_y'(0,0)$ 存在”的（　　）.",
    ["充分非必要条件", "必要非充分条件", "充分必要条件", "既非充分也非必要条件"], "C",
    "若 $g(0,0)=0$，则 $\\lim_{x\\to 0}\\frac{f(x,0)-f(0,0)}{x}=\\lim_{x\\to 0}\\frac{g(x,0)\\cdot|x|}{x}=0$，即 $f'_x(0,0)=0$；同理 $\\lim_{y\\to 0}\\frac{f(0,y)-f(0,0)}{y}=\\lim_{y\\to 0}\\frac{g(0,y)\\cdot|y|}{y}=0$，即 $f'_y(0,0)=0$。反之，若两个偏导极限存在，则满足 $\\lim_{x\\to 0^+}g(x,0)\\frac{|x|}{x}=\\lim_{x\\to 0^+}g(x,0)\\frac{|x|}{x}$，$\\lim_{y\\to 0^+}g(0,y)\\frac{|y|}{y}=\\lim_{y\\to 0^+}g(0,y)\\frac{|y|}{y}$，可得 $g(0,0)=-g(0,0)$，即 $g(0,0)=0$。因此 $f'_x(0,0),\\ f'_y(0,0)$ 存在的充要条件是 $g(0,0)=0$，答案选 (C)。"),
  Q(5, "线代", "二次型惯性指数", "中档", 3,
    "设二次型 $f\\left(x_1,x_2,x_3\\right)=\\left(x_1+kx_2\\right)^2+\\left(x_1+x_3\\right)^2-\\left[x_1-2x_2+(k+2)x_3\\right]^2$ 的负惯性指数为 0，则 $k=$（　　）.",
    ["$-1$", "1", "$-2$", "2"], "C",
    "作换元 $\\begin{cases}y_1=x_1+kx_2,\\\\ y_2=x_1+x_3,\\\\ y_3=x_1-2x_2+(k+2)x_3,\\end{cases}$ 即 $y=Px=\\begin{pmatrix}1&k&0\\\\1&0&1\\\\1&-2&k+2\\end{pmatrix}x$。① 若 $|P|\\neq 0$，矩阵 $P$ 可逆时，标准型为 $f=y_1^2+y_2^2-y_3^2$，不满足要求；② 若 $|P|=0$，$\\begin{vmatrix}1&k&0\\\\1&0&1\\\\1&-2&k+2\\end{vmatrix}=-(k+2)(k-1)=0$，得 $k=1,-2$。当 $k=1$ 时，取 $x_1=0,x_2=0,x_3=1$，此时 $f(0,0,1)=-8<0$，不满足要求；当 $k=-2$ 时，$f(x_1,x_2,x_3)=(x_1+x_3)^2\\ge 0$，满足要求，故 $k=-2$，答案选 (C)。"),
  Q(6, "线代", "线性方程组解的结构", "中档", 3,
    "若三阶矩阵 $A$ 满足 $r(A)=1$，且 $(2,0,-1)^T,(4,2,-1)^T$ 为非齐次线性方程组 $Ax=b$ 的解向量，则下列向量中必定为 $Ax=b$ 解向量的是（　　）.",
    ["$\\alpha_1=(2,2,0)^T$", "$\\alpha_2=(3,1,-1)^T$", "$\\alpha_3=(1,2,3)^T$", "$\\alpha_4=(2,1,-2)^T$"], "B",
    "记 $\\xi_1=(2,0,-1)^T,\\ \\xi_2=(4,2,-1)^T$，则 $A\\xi_1=b,\\ A\\xi_2=b$，且 $A(k_1\\xi_1+k_2\\xi_2)=k_1b+k_2b=(k_1+k_2)b$，故当 $k_1+k_2=1$ 时，$k_1\\xi_1+k_2\\xi_2$ 也是 $Ax=b$ 的解。要判断 $\\alpha_1,\\alpha_2,\\alpha_3,\\alpha_4$ 是否为 $Ax=b$ 的解向量，即判断哪个向量可由 $\\xi_1,\\xi_2$ 线性组合得到且组合的系数和为 1。将 $\\xi_1,\\xi_2,\\alpha_1,\\alpha_2,\\alpha_3,\\alpha_4$ 合并成矩阵做初等行变换，可验证仅 $\\alpha_2=(3,1,-1)^T$ 满足条件，答案选 (B)。"),
  Q(7, "线代", "实对称矩阵合同相似", "难题", 4,
    "若矩阵 $A,B$ 均为三阶实对称矩阵，且矩阵 $A,B$ 可逆，则下列四个命题中成立的个数是（　　）.\\n① 存在可逆矩阵 $P$，使得 $P^TAP=B$.　　② 存在可逆矩阵 $P$，使得 $A^2=P^TP$.\\n③ 存在可逆矩阵 $P$，使得 $P^TA^2P=B^2$.　　④ 存在可逆矩阵 $P$，使得 $P^{-1}ABP=BA$.",
    ["1", "2", "3", "4"], "C",
    "① 条件仅有矩阵 $A,B$ 可逆，但 $A,B$ 特征值的正负性不一定相同，故 $A,B$ 不一定合同，命题①错误。② $A$ 可逆，$\\lambda(A)=\\lambda_1,\\lambda_2,\\lambda_3\\neq0$，则 $\\lambda(A^2)=\\lambda_1^2,\\lambda_2^2,\\lambda_3^2>0$，故 $A^2$ 与 $E$ 合同，必存在可逆矩阵 $Q$ 使得 $Q^TA^2Q=E$，即 $A^2=(Q^{-1})^T(Q^{-1})$。取 $P=Q^{-1}$，则 $A^2=P^TP$，命题②正确。③ 由②，$A^2$ 的特征值均大于 0，同理 $B^2$ 的特征值均大于 0，故 $A^2$ 与 $B^2$ 合同，即存在可逆矩阵 $P$ 使 $P^TA^2P=B^2$，命题③正确。④ 若 $P=A$，则 $P^{-1}ABP=BA$，命题④正确。因此答案选 (C)。"),
  Q(8, "概率", "条件概率与独立性", "中档", 3,
    "随机事件 $A,B,C$ 相互独立，满足 $P(A)=\\dfrac{1}{2},P(A-B)=\\dfrac{1}{3},P(C)=\\dfrac{2}{5}$，则 $P\\left\\{(C-A)\\left|\\left(A\\cup BC\\right)\\right.\\right\\}=$（　　）.",
    ["$\\dfrac{1}{9}$", "$\\dfrac{2}{17}$", "$\\dfrac{4}{17}$", "$\\dfrac{2}{9}$"], "B",
    "$A,B$ 独立，则 $P(A-B)=P(A)-P(AB)=P(A)-P(A)P(B)=\\frac{1}{3}$，由 $P(A)=\\frac{1}{2}$ 可得 $P(B)=\\frac{1}{3}$。$$P\\{(C-A)|(A\\cup BC)\\}=P\\{C\\bar A|(A+BC)\\}=\\frac{P(C\\bar A(A+BC))}{P(A)+P(BC)-P(ABC)}=\\frac{P(\\bar A)P(B)P(C)}{P(A)+P(B)P(C)-P(A)P(B)P(C)}$$ $$=\\frac{\\frac{1}{2}\\times\\frac{1}{3}\\times\\frac{2}{5}}{\\frac{1}{2}+\\frac{1}{3}\\times\\frac{2}{5}-\\frac{1}{2}\\times\\frac{1}{3}\\times\\frac{2}{5}}=\\frac{2}{17}.$$ 因此答案选 (B)。"),
  Q(9, "概率", "正态分布对称性", "常规", 2,
    "设随机变量 $X$ 与 $Y$ 相互独立，且 $X\\sim N(1,2),Y\\sim N(-1,4)$，若满足等式 $P\\left\\{X<Y\\right\\}=P\\left\\{X+2Y>a\\right\\}$，则 $a=$（　　）.",
    ["$2\\sqrt{3}-1$", "$-2\\sqrt{3}+1$", "$\\sqrt{6}-1$", "$-\\sqrt{6}+1$"], "A",
    "由 $X\\sim N(1,2)$，$Y\\sim N(-1,4)$ 且独立，可得 $X-Y\\sim N(2,6)$，$\\frac{(X-Y)-2}{\\sqrt6}\\sim N(0,1)$，$X+2Y\\sim N(-1,18)$，$\\frac{(X+2Y)+1}{3\\sqrt2}\\sim N(0,1)$。所以 $P\\{X<Y\\}=P\\{X-Y<0\\}=\\Phi\\left(-\\frac{2}{\\sqrt6}\\right)$，而 $P\\{X+2Y>a\\}=1-\\Phi\\left(\\frac{a+1}{3\\sqrt2}\\right)$。由 $\\Phi\\left(-\\frac{2}{\\sqrt6}\\right)=1-\\Phi\\left(\\frac{a+1}{3\\sqrt2}\\right)$ 得 $\\frac{a+1}{3\\sqrt2}=\\frac{2}{\\sqrt6}$，解得 $a=2\\sqrt3-1$，答案选 (A)。"),
  Q(10, "概率", "统计量期望", "中档", 3,
    "设 $X_1,X_2,\\cdots X_{2n}\\ (n\\ge 2)$ 为来自总体 $X$ 的简单随机样本，$X\\sim N\\left(\\mu,\\sigma^2\\right)(\\sigma>0)$，$\\overline{X}=\\dfrac{1}{2n}\\sum\\limits_{i=1}^{2n}X_i$ 为样本均值. 记统计量 $Y_1=\\sum\\limits_{i=1}^{2n}(X_i-\\overline{X})^2,Y_2=\\sum\\limits_{i=1}^{n}(X_i-X_{n+i})^2,Y_3=\\sum\\limits_{i=1}^{n}(X_i+X_{n+i}-2\\overline{X})^2$，则这三个统计量的数学期望 $E\\left(Y_1\\right),E\\left(Y_2\\right),E\\left(Y_3\\right)$ 的大小关系为（　　）.",
    ["$E\\left(Y_1\\right)>E\\left(Y_2\\right)>E\\left(Y_3\\right)$", "$E\\left(Y_2\\right)>E\\left(Y_3\\right)>E\\left(Y_1\\right)$", "$E\\left(Y_3\\right)>E\\left(Y_1\\right)>E\\left(Y_2\\right)$", "$E\\left(Y_2\\right)>E\\left(Y_1\\right)>E\\left(Y_3\\right)$"], "D",
    "对于 $Y_1$：样本方差 $S^2=\\frac{1}{2n-1}\\sum_{i=1}^{2n}(X_i-\\bar X)^2$ 满足 $\\frac{(2n-1)S^2}{\\sigma^2}\\sim\\chi^2(2n-1)$，故 $E(Y_1)=(2n-1)\\sigma^2$。对于 $Y_2$：$E(X_i-X_{n+i})=0$，$D(X_i-X_{n+i})=2\\sigma^2$，且相互独立，故 $\\sum_{i=1}^{n}\\left(\\frac{X_i-X_{n+i}}{\\sqrt2\\sigma}\\right)^2\\sim\\chi^2(n)$，$E(Y_2)=2n\\sigma^2$。对于 $Y_3$：$X_i+X_{n+i}$ 可看作来自 $N(2\\mu,2\\sigma^2)$ 的样本，样本均值为 $2\\bar X$，样本方差为 $\\frac{1}{n-1}Y_3$，故 $\\frac{Y_3}{2\\sigma^2}\\sim\\chi^2(n-1)$，$E(Y_3)=2(n-1)\\sigma^2$。综上 $E(Y_2)>E(Y_1)>E(Y_3)$，选 (D)。"),
  Q(11, "高数", "幂指函数极限", "中档", 3,
    "$\\lim\\limits_{x\\to+\\infty}\\left(\\dfrac{x^{\\frac{1}{x}}+1}{2}\\right)^{\\frac{x}{\\ln x}}=$________.",
    null, "e^{\\frac{1}{2}}",
    "$$\\lim_{x\\to+\\infty}\\left(\\frac{x^{\\frac1x}+1}{2}\\right)^{\\frac{x}{\\ln x}}=e^{\\lim\\limits_{x\\to+\\infty}\\frac{x}{\\ln x}\\cdot\\ln\\left(\\frac{x^{\\frac1x}+1}{2}\\right)},$$ 而 $$\\lim_{x\\to+\\infty}\\frac{x}{\\ln x}\\cdot\\ln\\left(\\frac{x^{\\frac1x}+1}{2}\\right)=\\lim_{x\\to+\\infty}\\frac{x}{\\ln x}\\cdot\\frac{x^{\\frac1x}-1}{2}=\\lim_{x\\to+\\infty}\\frac{x}{\\ln x}\\cdot\\frac{e^{\\frac{1}{x}\\ln x}-1}{2}=\\lim_{x\\to+\\infty}\\frac{x}{\\ln x}\\cdot\\frac{\\frac{1}{x}\\ln x}{2}=\\frac{1}{2},$$ 故 $\\lim\\limits_{x\\to+\\infty}\\left(\\frac{x^{\\frac1x}+1}{2}\\right)^{\\frac{x}{\\ln x}}=e^{\\frac{1}2}$。"),
  Q(12, "高数", "隐函数求导", "中档", 3,
    "设函数 $y=y(x)$ 可由方程 $xy+\\displaystyle\\int_0^{xy}e^{t^2}dt+1=x+e^y$ 确定，则 $\\left.\\dfrac{dy}{dx}\\right|_{x=0}=$________.",
    null, "-1",
    "当 $x=0$ 时，由原方程得 $y(0)=0$。在方程 $xy+\\int_0^{xy}e^{t^2}dt+1=x+e^y$ 两边对 $x$ 求导，得 $y+xy'+e^{x^2y^2}\\cdot(y+xy')=1+e^y y'$，代入 $x=0,\\ y(0)=0$，得 $y'(0)=-1$。"),
  Q(13, "高数", "条件极值", "常规", 2,
    "某产品的产量 $Q$ 由资本投入量 $x$ 和劳动投入量 $y$ 决定，$Q=\\sqrt{xy}$. 若单位资本投入和单位劳动投入的价格分别为 $p_1,p_2\\left(p_1,p_2>0\\right)$. 当产量 $Q$ 为 $q$ 时，投入成本最少为________.",
    null, "2q\\sqrt{p_1p_2}",
    "在约束 $\\sqrt{xy}=q$ 下求 $f(x,y)=p_1x+p_2y$ 的最小值。构造拉格朗日函数 $L(x,y,\\lambda)=p_1x+p_2y+\\lambda(\\sqrt{xy}-q)$，由 $$\\begin{cases}\\frac{\\partial L}{\\partial x}=p_1+\\frac{1}{2}\\lambda x^{-\\frac{1}2}y^{\\frac{1}2}=0\\\\\\frac{\\partial L}{\\partial y}=p_2+\\frac{1}{2}\\lambda x^{\\frac{1}2}y^{-\\frac{1}2}=0\\\\\\frac{\\partial L}{\\partial\\lambda}=x^{\\frac{1}2}y^{\\frac{1}2}-q=0\\end{cases}$$ 解得 $x=q\\sqrt{\\frac{p_2}{p_1}},\\ y=q\\sqrt{\\frac{p_1}{p_2}}$。于是 $f(x,y)$ 在约束条件 $\\sqrt{xy}=q$ 下的条件极值为 $2q\\sqrt{p_1p_2}$。"),
  Q(14, "高数", "微分方程与反常积分", "难题", 4,
    "已知函数 $f(x),g(x)$ 均为二阶常系数微分方程 $y''+py'+qy=0$ 的特解，且 $f(x)=(x+1)e^{-x}$，$g(x)$ 满足 $\\lim\\limits_{x\\to 0}\\dfrac{1-g(x)}{x}=1$，则 $\\displaystyle\\int_0^{+\\infty}xg(x)dx=$________.",
    null, "1",
    "由 $f(x)=(x+1)e^{-x}$ 满足 $y''+py'+qy=0$，可知特征方程有 2 个相同实根 $r_{1,2}=-1$，故通解为 $y=C_1e^{-x}+C_2xe^{-x}$，即 $g(x)=C_1e^{-x}+C_2xe^{-x}$。由 $\\lim\\limits_{x\\to0}\\frac{1-g(x)}{x}=1$ 可知 $\\lim\\limits_{x\\to0}g(x)=1$，又 $g(x)$ 必定连续，故 $g(0)=1$；同时 $\\lim\\limits_{x\\to0}\\frac{g(x)-1}{x}=-1\\Rightarrow\\lim\\limits_{x\\to0}\\frac{g(x)-g(0)}{x}=g'(0)=-1$。"),
  Q(15, "线代", "矩阵方程与行列式", "中档", 3,
    "矩阵 $A,B$ 均为三阶矩阵，其中矩阵 $A$ 不可逆，矩阵 $B$ 满足 $(A+E)B=O$，$r(B)=2$，则 $\\left|A+2E\\right|=$____.",
    null, "2",
    "矩阵 $A$ 不可逆，故矩阵 $A$ 必定存在特征值为 0。由条件 $(A+E)B=O$，可得 $AB=-B$，记矩阵 $B=(\\alpha_1,\\alpha_2,\\alpha_3)$，则 $A(\\alpha_1,\\alpha_2,\\alpha_3)=-(\\alpha_1,\\alpha_2,\\alpha_3)$，即矩阵 $B$ 的每一非零列向量均为 $A$ 对应特征值为 -1 的特征向量，又 $r(B)=2$，因此特征值 -1 对应有两个线性无关的特征向量，-1 至少是 $A$ 的二重特征值。由此可得，矩阵 $A$ 存在特征值为 0，又至少有二重特征值 -1，则 $\\lambda(A)=0,-1,-1$。因此 $\\lambda(A+2E)=2,1,1$，$|A+2E|=2$。"),
  Q(16, "概率", "条件概率密度", "中档", 3,
    "已知二维随机变量 $(X,Y)$ 的联合概率密度为 $f(x,y)=\\begin{cases}\\dfrac{1}{x}, & 0<y<x<1,\\\\ 0, & \\text{其他},\\end{cases}$ 则当 $0<x<1$ 时，条件概率 $P\\left\\{X+Y\\le 1\\middle|X=x\\right\\}=$________.",
    null, "\\begin{cases}1, & 0<x\\le\\dfrac{1}{2},\\\\ \\dfrac{1-x}{x}, & \\dfrac{1}{2}<x<1\\end{cases}",
    "边缘概率密度 $f_X(x)=\\int_{-\\infty}^{+\\infty}f(x,y)dy=\\begin{cases}\\int_0^x \\frac{1}{x}dy, & 0<x<1,\\\\ 0, & \\text{其他}\\end{cases}$，故条件概率密度 $f_{Y|X}(y|x)=\\frac{f(x,y)}{f_X(x)}=\\begin{cases}\\frac{1}{x}, & 0<y<x<1,\\\\ 0, & \\text{其他}\\end{cases}$。条件概率 $P\\{X+Y\\le 1|X=x\\}=P\\{Y\\le 1-X|X=x\\}=\\int_{-\\infty}^{1-x}f_{Y|X}(y|x)dy$。当 $x\\le 1-x$ 即 $x\\le\\frac{1}{2}$ 时，$P\\{Y\\le 1-X|X=x\\}=\\int_0^x \\frac{1}{x}dy=1$；当 $x>1-x$ 即 $\\frac{1}{2}<x$ 时，$P\\{Y\\le 1-X|X=x\\}=\\int_0^{1-x}\\frac{1}{x}dy=\\frac{1-x}{x}$。综上所述 $P\\{X+Y\\le 1|X=x\\}=\\begin{cases}1, & 0<x\\le\\frac{1}{2},\\\\ \\frac{1-x}{x}, & \\frac{1}{2}<x<1\\end{cases}$（注：写成 $x\\le\\frac{1}{2}$、$\\frac{1}{2}<x$ 不扣分）。"),
  Q(17, "高数", "二重积分对称性", "中档", 3,
    "设区域 $D=\\left\\{(x,y)\\middle|x^2+y^2\\le 1, x+y\\ge 0\\right\\}$，计算二重积分 $\\displaystyle\\iint_D\\frac{xy^2}{1+x^2+y^2}dxdy$.",
    null, "\\dfrac{\\sqrt{2}\\pi}{24}-\\dfrac{\\sqrt{2}}{9}",
    "用直线 $y=x$ 将区域 $D$ 分割成 $D_1$、$D_2$ 两部分，则 $\\iint_D \\frac{xy^2}{1+x^2+y^2}dxdy=\\iint_{D_1}\\frac{xy^2}{1+x^2+y^2}dxdy+\\iint_{D_2}\\frac{xy^2}{1+x^2+y^2}dxdy$。由于区域 $D_2$ 关于 $y$ 轴对称，故 $\\iint_{D_2}\\frac{xy^2}{1+x^2+y^2}dxdy=0$。而 $\\iint_D \\frac{xy^2}{1+x^2+y^2}dxdy=\\iint_{D_1}\\frac{xy^2}{1+x^2+y^2}dxdy=2\\iint_{D_{12}}\\frac{xy^2}{1+x^2+y^2}dxdy=2\\int_0^{\\frac{\\pi}{4}}d\\theta\\int_0^1 \\frac{r^3\\cos\\theta\\sin^2\\theta}{1+r^2}rdr$（$D_{12}$ 为 $D_1$ 中 $y\\ge x$ 的对称一半，利用对称性）$=2\\int_0^{\\frac{\\pi}{4}}\\cos\\theta\\sin^2\\theta d\\theta\\int_0^1\\frac{r^4}{1+r^2}dr=2\\int_0^{\\frac{\\pi}{4}}\\cos\\theta\\sin^2\\theta d\\theta\\int_0^1\\left(r^2-1+\\frac{1}{1+r^2}\\right)dr=\\frac{\\sqrt{2}\\pi}{24}-\\frac{\\sqrt{2}}{9}$。因此 $\\iint_D \\frac{xy^2}{1+x^2+y^2}dxdy=\\frac{\\sqrt{2}\\pi}{24}-\\frac{\\sqrt{2}}{9}$。"),
  Q(18, "高数", "函数方程与切线", "难题", 4,
    "设连续的奇函数 $y=f(x)$ 在 $x=1$ 处可导，且在 $x=0$ 的去心邻域内满足等式\\n$$2f(x)+f(-x)=\\frac{\\sqrt{1+2f\\left(e^x\\right)}-\\sqrt{1-f\\left(1-\\tan x\\right)}}{x}-1.$$\\n试求 $y=f(x)$ 在 $x=-1$ 处的切线方程.",
    null, "y=2x+2",
    "由条件可得 $\\lim_{x\\to 0}[2f(x)+f(-x)]=\\lim_{x\\to 0}\\left[\\frac{\\sqrt{1+2f(e^x)}-\\sqrt{1-f(1-\\tan x)}}{x}\\right]-1$。因为 $f(x)$ 连续，$\\lim_{x\\to 0}[2f(x)+f(-x)]=3f(0)=0$（$f$ 为奇函数故 $f(0)=0$），则 $\\lim_{x\\to 0}\\left[\\frac{\\sqrt{1+2f(e^x)}-\\sqrt{1-f(1-\\tan x)}}{x}\\right]=1$。又 $\\lim_{x\\to 0}\\left[\\sqrt{1+2f(e^x)}-\\sqrt{1-f(1-\\tan x)}\\right]=\\sqrt{1+2f(1)}-\\sqrt{1-f(1)}=0$，可得 $f(1)=0$。分子有理化：$\\lim_{x\\to 0}\\frac{\\sqrt{1+2f(e^x)}-\\sqrt{1-f(1-\\tan x)}}{x}=\\lim_{x\\to 0}\\frac{2f(e^x)+f(1-\\tan x)}{2x}=\\lim_{x\\to 0}\\left[\\frac{f(e^x)-f(1)}{e^x-1}\\cdot\\frac{e^x-1}{x}+\\frac{f(1-\\tan x)-f(1)}{-\\tan x}\\cdot\\frac{-\\tan x}{2x}\\right]=f'(1)-\\frac{1}{2}f'(1)=\\frac{1}{2}f'(1)=1$，所以 $f'(1)=2$。（注：本题计算极限时不能使用洛必达，使用洛必达计算的直接扣 6 分。）由 $y=f(x)$ 为奇函数，$f(-1)=-f(1)=0$，$f'(-1)=f'(1)=2$，因此 $y=f(x)$ 在 $x=-1$ 处的切线方程为 $y=2x+2$。"),
  Q(19, "高数", "定积分与级数求和", "难题", 4,
    "若函数 $y=x\\cos\\left(\\dfrac{x}{n}\\right)$（$n$ 为正整数）在区间 $[0,n\\pi]$ 上与 $x$ 轴所围成的面积记作 $A_n$，计算级数 $\\displaystyle\\sum_{n=1}^{\\infty}(-1)^n\\frac{A_n}{2^n}$.",
    null, "-\\dfrac{2}{27}\\pi",
    "$A_n=\\int_0^{n\\pi}x\\left|\\cos\\frac{x}{n}\\right|dx$，令 $t=\\frac{x}{n}$，$A_n=\\int_0^{\\pi}n^2 t|\\cos t|dt=n^2\\int_0^{\\frac{\\pi}{2}}t\\cos t\\,dt-n^2\\int_{\\frac{\\pi}{2}}^{\\pi}t\\cos t\\,dt$。由 $\\int_0^{\\frac{\\pi}{2}}t\\cos t\\,dt=\\frac{\\pi}{2}-1$，$\\int_{\\frac{\\pi}{2}}^{\\pi}t\\cos t\\,dt=-\\frac{\\pi}{2}-1$，故 $A_n=n^2\\int_0^{\\frac{\\pi}{2}}t\\cos t\\,dt-n^2\\int_{\\frac{\\pi}{2}}^{\\pi}t\\cos t\\,dt=\\pi n^2$。令 $S(x)=\\sum_{n=1}^{\\infty}(-1)^n\\frac{A_n}{2^n}x^n=\\sum_{n=1}^{\\infty}(-1)^n\\frac{\\pi n^2}{2^n}x^n$，则 $\\sum_{n=1}^{\\infty}(-1)^n\\frac{A_n}{2^n}=S(1)$。由比值法可得收敛域为 $-2<x<2$（$x=\\pm 2$ 时通项极限不为 0，发散）。令 $S(x)=\\pi\\sum_{n=1}^{\\infty}n^2\\left(-\\frac{x}{2}\\right)^n$，取 $-\\frac{x}{2}=t$，则 $S(x)=\\pi\\sum_{n=1}^{\\infty}n^2 t^n=\\pi t\\sum_{n=1}^{\\infty}n^2 t^{n-1}=\\pi t\\left(\\sum_{n=1}^{\\infty}nt^n\\right)'$，记 $S_1(x)=\\sum_{n=1}^{\\infty}nt^n=t\\left(\\sum_{n=1}^{\\infty}t^n\\right)'=\\frac{t}{(1-t)^2}$，则 $S(x)=\\pi t\\left[\\frac{t}{(1-t)^2}\\right]'=\\pi t\\cdot\\frac{t+1}{(1-t)^3}=\\frac{\\pi\\left(-\\frac{x}{2}\\right)\\left(-\\frac{x}{2}+1\\right)}{\\left(1+\\frac{x}{2}\\right)^3}=\\frac{2\\pi x(x-2)}{(2+x)^3}$。因此 $\\sum_{n=1}^{\\infty}(-1)^n\\frac{A_n}{2^n}=S(1)=-\\frac{2}{27}\\pi$。"),
  Q(20, "高数", "数列极限与单调有界", "难题", 4,
    "若数列 $\\left\\{x_n\\right\\}$ 满足 $x_{n+1}=1+\\ln\\left(\\dfrac{x_n^2}{1+\\ln x_n}\\right)$，其中 $n=1,2,\\ldots$，且 $x_1=a>1$.\\n（1）证明：对于任意的正整数 $n$，都有 $x_n>1$.\\n（2）证明数列 $\\left\\{x_n\\right\\}$ 收敛，并计算 $\\lim\\limits_{n\\to\\infty}x_n$.",
    null, "（所提供的解析页仅包含第（1）—（6）题，未包含第 20 题的内容，无法识别）",
    "（1）记 $f(x)=x^2-1-\\ln x$，$x\\ge 1$，则 $f'(x)=2x-\\frac{1}{x}>0$，$f(x)$ 在 $[1,+\\infty)$ 上单调递增，因此当 $x\\ge 1$ 时，$f(x)>f(1)=0$，即 $x>1$ 时 $x^2>1+\\ln x$。因此当 $x_1=a>1$ 时，$x_1^2-1-\\ln x_1>0$，即 $\\frac{x_1^2}{1+\\ln x_1}>1$，$\\ln\\left(\\frac{x_n^2}{1+\\ln x_n}\\right)>0$，故 $x_2=1+\\ln\\left(\\frac{x_1^2}{1+\\ln x_1}\\right)>1$。"),
  Q(21, "线代", "矩阵相似对角化", "难题", 4,
    "若矩阵 $A=\\begin{pmatrix}5 & -a & 0\\\\ 1 & a+2 & 0\\\\ 0 & 0 & 2\\end{pmatrix}$ 不可相似对角化，其中 $a$ 为参数.\\n（1）计算 $a$ 的取值；\\n（2）判断是否存在可逆矩阵 $P$，使得 $P^{-1}AP=B$，其中 $B=\\begin{pmatrix}2a+2 & 2 & 0\\\\ 0 & 2a+2 & 0\\\\ 0 & 0 & 2\\end{pmatrix}$. 若不存在，说明理由；若存在，试找出一个满足的可逆矩阵 $P$.",
    null, "(1) $a=1$ 或 $a=9$；(2) $a=9$ 时不存在，$a=1$ 时存在 $P=\\begin{pmatrix}k_1&2k_1+k_2&0\\\\k_1&k_2&0\\\\0&0&k_3\\end{pmatrix}$（$k_1\\ne0,k_3\\ne0$）",
    "(1) $|A-\\lambda E|=(2-\\lambda)\\left[\\lambda^2-(a+7)\\lambda+6a+10\\right]$。① 若 $\\lambda=2$ 为三重特征值，则 $a+7=4,6a+10=4$，无解。② 若 $\\lambda=2$ 为二重特征值，代入得 $a=0$，此时 $r(A-2E)=1$，$\\lambda=2$ 对应两个线性无关特征向量，$A$ 可相似对角化，不满足。③ 若 $\\lambda^2-(a+7)\\lambda+6a+10=0$ 出现二重根，$\\Delta=a^2-10a+9=(a-1)(a-9)=0$。当 $a=1$ 时 $\\lambda=4$ 为二重特征值，$r(A-4E)=2$，只有一个线性无关特征向量，不能相似对角化，满足；当 $a=9$ 时 $\\lambda=8$ 为二重特征值，$r(A-8E)=2$，也不能相似对角化，满足。综上 $a=1$ 或 $a=9$。(2) 当 $a=9$ 时，$B$ 的特征值为 $20,20,2$ 与 $A$ 的特征值不同，故 $A$ 必定不可能相似于 $B$。当 $a=1$ 时，$B=\\begin{pmatrix}4&2&0\\\\0&4&0\\\\0&0&2\\end{pmatrix}$，设 $P=(\\alpha_1,\\alpha_2,\\alpha_3)$ 满足 $P^{-1}AP=B$，即 $A\\alpha_1=4\\alpha_1$，$A\\alpha_2=2\\alpha_1+4\\alpha_2$，$A\\alpha_3=2\\alpha_3$。解 $(A-4E)\\alpha_1=0$ 得 $\\alpha_1=\\begin{pmatrix}k_1\\\\k_1\\\\0\\end{pmatrix}$；由 $(A-4E)\\alpha_2=2\\alpha_1$ 解得 $\\alpha_2=\\begin{pmatrix}2k_1+k_2\\\\k_2\\\\0\\end{pmatrix}$；由 $(A-2E)\\alpha_3=0$ 解得 $\\alpha_3=\\begin{pmatrix}0\\\\0\\\\k_3\\end{pmatrix}$。$|P|=-2k_1^2k_3\\ne0$，故当 $a=1$ 时存在 $P=\\begin{pmatrix}k_1&2k_1+k_2&0\\\\k_1&k_2&0\\\\0&0&k_3\\end{pmatrix}$，其中 $k_1\\ne0,k_3\\ne0$，使得 $P^{-1}AP=B$。"),
  Q(22, "概率", "随机变量函数与参数估计", "难题", 4,
    "设随机变量 $X$ 与 $Y$ 相互独立，且 $X$ 在区间 $[-2,2]$ 上服从均匀分布，$Y$ 的概率密度为 $f(y)=\\dfrac{\\lambda}{2}e^{-\\lambda|y|}$，$-\\infty<y<+\\infty$，其中参数 $\\lambda(\\lambda>0)$ 未知. 令 $Z=\\begin{cases}2Y, & X\\ge 1,\\\\ -2Y, & X<1.\\end{cases}$\\n（1）求随机变量 $Z$ 的概率密度；\\n（2）若 $Z_1,Z_2,\\cdots,Z_n$ 为来自总体 $Z$ 的简单随机样本，求参数 $\\lambda$ 的矩估计量和最大似然估计量.",
    null, "(1) $f_Z(z)=\\dfrac{\\lambda}{4}e^{-\\frac{\\lambda}{2}|z|},z\\in(-\\infty,+\\infty)$；(2) $\\hat\\lambda_1=\\sqrt{8n\\Big/\\sum\\limits_{i=1}^n Z_i^2}$，$\\hat\\lambda_2=2n\\Big/\\sum\\limits_{i=1}^n|Z_i|$",
    "(1) $F_Z(z)=P\\{Z\\le z\\}=P\\{2Y\\le z,X\\ge1\\}+P\\{-2Y\\le z,X<1\\}=\\dfrac{1}{4}P\\{Y\\le\\tfrac{z}{2}\\}+\\dfrac{3}{4}P\\{Y\\ge-\\tfrac{z}{2}\\}=\\dfrac{1}{4}F_Y(\\tfrac{z}{2})+\\dfrac{3}{4}[1-F_Y(-\\tfrac{z}{2})]$。求导得 $f_Z(z)=\\dfrac{1}{8}f_Y(\\tfrac{z}{2})+\\dfrac{3}{8}f_Y(-\\tfrac{z}{2})=\\dfrac{\\lambda}{16}e^{-\\frac{\\lambda|z|}{2}}+\\dfrac{3\\lambda}{16}e^{-\\frac{\\lambda|z|}{2}}=\\dfrac{\\lambda}{4}e^{-\\frac{\\lambda|z|}{2}}$，$z\\in(-\\infty,+\\infty)$。(2) ① 矩估计：$EZ=0$，选用二阶原点矩，$EZ^2=\\int_{-\\infty}^{+\\infty}z^2\\cdot\\dfrac{\\lambda}{4}e^{-\\frac{\\lambda|z|}{2}}dz=\\dfrac{\\lambda}{2}\\int_0^{+\\infty}z^2e^{-\\frac{\\lambda}{2}z}dz=\\dfrac{\\lambda}{2}\\cdot\\dfrac{8}{\\lambda^3}\\int_0^{+\\infty}t^2e^{-t}dt=\\dfrac{8}{\\lambda^2}$。令 $EZ^2=\\dfrac{1}{n}\\sum Z_i^2$，得 $\\hat\\lambda_1=\\sqrt{8n/\\sum_{i=1}^n Z_i^2}$。② 最大似然估计：$L(\\lambda)=\\left(\\dfrac{\\lambda}{4}\\right)^ne^{-\\frac{\\lambda}{2}\\sum|Z_i|}$，$\\ln L(\\lambda)=n\\ln\\lambda-n\\ln4-\\dfrac{\\lambda}{2}\\sum_{i=1}^n|Z_i|$，令 $\\dfrac{d\\ln L}{d\\lambda}=\\dfrac{n}{\\lambda}-\\dfrac{1}{2}\\sum|Z_i|=0$，解得 $\\hat\\lambda_2=2n/\\sum_{i=1}^n|Z_i|$。"),
];
